export const topics = [{"id":"eq","block":"math","name":"Теңдеулер және ықшамдау","nameRu":"Уравнения и упрощение"},{"id":"num","block":"math","name":"Сандар және бөлінгіштік","nameRu":"Числа и делимость"},{"id":"work","block":"math","name":"Жұмыс және өнімділік","nameRu":"Работа и производительность"},{"id":"ratio","block":"math","name":"Бөліктер, қатынастар, қозғалыс","nameRu":"Части, отношения, движение"},{"id":"geo","block":"math","name":"Геометрия","nameRu":"Геометрия"},{"id":"frac","block":"math","name":"Есептеулер және бөлшектер","nameRu":"Вычисления и дроби"},{"id":"pct","block":"math","name":"Пайыздар","nameRu":"Проценты"},{"id":"sys","block":"math","name":"Теңдеулер жүйесі, теңсіздіктер","nameRu":"Системы и неравенства"},{"id":"seq","block":"logic","name":"Фигуралар/сандар тізбегі","nameRu":"Последовательности"},{"id":"mtx","block":"logic","name":"Матрицалар және аналогиялар","nameRu":"Матрицы и аналогии"},{"id":"spat","block":"logic","name":"Кеңістіктік ойлау","nameRu":"Пространственное мышление"},{"id":"comb","block":"logic","name":"Сандық/комбинаторлық логика","nameRu":"Числовая и комбинаторная логика"}];

export const questions = [{"id":"v1_1","school":"РФМШ","variant":"v1","num":1,"topic":"spat","difficulty":3,"statement":"Какая грань будет сверху, если кубик из данной развёртки поставить на закрашенную грань?","answer":"4","solution":"Полоса 2–серая–3–4 сворачивается в 4 боковые грани, где серая грань оказывается напротив грани 4. Если поставить кубик на серую грань, сверху окажется 4.","image":"/figures/v1_q1.png"},{"id":"v1_2","school":"РФМШ","variant":"v1","num":2,"topic":"eq","difficulty":2,"statement":"Бахыт старше сына в 5 раз, сумма их возрастов 360 месяцев (30 лет). Через сколько лет Бахыт будет старше сына в 3 раза?","answer":"5","solution":"Сын 5, Бахыт 25. 25+t=3(5+t) → 10=2t → t=5 лет.","image":null},{"id":"v1_3","school":"РФМШ","variant":"v1","num":3,"topic":"work","difficulty":2,"statement":"У Асана 12 годовых оценок, средний балл 3,75. По скольким предметам поднять оценку на 1 балл, чтобы средний стал 4?","answer":"3","solution":"Сумма=45. Для среднего 4 нужна сумма 48. Разница 3 → поднять 3 предмета.","image":null},{"id":"v1_4","school":"РФМШ","variant":"v1","num":4,"topic":"pct","difficulty":2,"statement":"Спортсекции посещают 360 студентов = 40% от всех. 10% всех ходят на английский. 30% из тех, кто на английском, занимаются танцами. Сколько танцуют?","answer":"27","solution":"Всего 900. Английский 90. Танцы 30% от 90 = 27.","image":null},{"id":"v1_5","school":"РФМШ","variant":"v1","num":5,"topic":"pct","difficulty":2,"statement":"Число жирафов равно 80% от числа обезьян. Сколько процентов от жирафов составляют обезьяны?","answer":"125%","solution":"G=0,8·M → M/G = 1,25 = 125%.","image":null},{"id":"v1_6","school":"РФМШ","variant":"v1","num":6,"topic":"eq","difficulty":2,"statement":"Найдите a, при котором значения выражений (2(a+b+x)−3a−3(−a−2b)−8b)/2 и x+2 равны.","answer":"2","solution":"Числитель = 2a+2x, делённое на 2 даёт a+x. a+x = x+2 → a=2.","image":null},{"id":"v1_7","school":"РФМШ","variant":"v1","num":7,"topic":"num","difficulty":1,"statement":"Если сегодня вторник, какой день недели будет через 340 дней? (Ответ — номер дня от 1 до 7, понедельник = 1.)","answer":"6","solution":"340 mod 7 = 4. Вторник + 4 = суббота = 6.","image":null},{"id":"v1_8","school":"РФМШ","variant":"v1","num":8,"topic":"comb","difficulty":3,"statement":"Семь человек за круглым столом, каждый говорит: оба моих соседа лжецы. Лжецы всегда лгут, остальные всегда правдивы. Сколько лжецов?","answer":"4","solution":"Правдивый окружён лжецами, у каждого лжеца есть хотя бы один правдивый сосед. На 7 местах это даёт 4 лжеца.","image":null},{"id":"v1_9","school":"РФМШ","variant":"v1","num":9,"topic":"num","difficulty":3,"statement":"Шестизначное число 1234ab кратно 9 и состоит из разных цифр. Какое наибольшее значение принимает a·b?","answer":"72","solution":"Сумма цифр 10+a+b кратна 9 → a+b=17 (из свободных 0,5,6,7,8,9). 8·9 = 72.","image":null},{"id":"v1_10","school":"РФМШ","variant":"v1","num":10,"topic":"geo","difficulty":1,"statement":"Вычислите x, если точки A, O, D лежат на одной прямой (углы 50°, 3x°, 2x°).","answer":"26","solution":"50 + 3x + 2x = 180 → 5x = 130 → x = 26.","image":"/figures/v1_q10.png"},{"id":"v1_11","school":"РФМШ","variant":"v1","num":11,"topic":"eq","difficulty":2,"statement":"Найдите целый корень уравнения: (5,5 + |6x+4|:2)/3 = 4,5.","answer":"2","solution":"5,5 + |6x+4|/2 = 13,5 → |6x+4| = 16 → x=2 (целый).","image":null},{"id":"v1_12","school":"РФМШ","variant":"v1","num":12,"topic":"sys","difficulty":1,"statement":"Найдите сумму всех целых решений неравенства: 9 < 2x+3 ≤ 13.","answer":"9","solution":"3 < x ≤ 5 → x=4,5. Сумма = 9.","image":null},{"id":"v1_13","school":"РФМШ","variant":"v1","num":13,"topic":"pct","difficulty":3,"statement":"На первой остановке израсходовано 20% бензина, на второй 25% остатка. Оставшегося на 10 л больше израсходованного. Сколько литров было изначально?","answer":"50","solution":"Израсходовано 0,4V, осталось 0,6V. 0,6V−0,4V=0,2V=10 → V=50.","image":null},{"id":"v1_14","school":"РФМШ","variant":"v1","num":14,"topic":"geo","difficulty":2,"statement":"Точки P(−5;0) и F(−1;4), F — середина отрезка PB. Найдите сумму координат точки B.","answer":"11","solution":"B = 2F − P = (3;8). Сумма = 11.","image":null},{"id":"v1_15","school":"РФМШ","variant":"v1","num":15,"topic":"geo","difficulty":2,"statement":"Площадь первого колеса 1600π, второго 400π. Радиус третьего = 50% суммы радиусов первых двух. Найдите площадь третьего (π=3,14).","answer":"2826","solution":"r1=40, r2=20, r3=30. S = π·900 = 2826.","image":null},{"id":"v1_16","school":"РФМШ","variant":"v1","num":16,"topic":"work","difficulty":3,"statement":"20 человек несут 200 кг: мужчина 20 кг, женщина 5 кг, ребёнок 3 кг. Найдите произведение чисел мужчин, женщин и детей.","answer":"160","solution":"m=8, w=2, c=10. Произведение = 160.","image":null},{"id":"v1_17","school":"РФМШ","variant":"v1","num":17,"topic":"pct","difficulty":2,"statement":"Все цены снизили на 15%. Скидочная цена шоколада 2210 тг. На сколько тг подешевел шоколад?","answer":"390","solution":"Исходная 2210/0,85 = 2600. Скидка = 390.","image":null},{"id":"v1_18","school":"РФМШ","variant":"v1","num":18,"topic":"geo","difficulty":2,"statement":"Измерения прямоугольного параллелепипеда — простые числа, объём 42. Найдите площадь поверхности.","answer":"82","solution":"42=2·3·7. S = 2(6+21+14) = 82.","image":null},{"id":"v1_19","school":"РФМШ","variant":"v1","num":19,"topic":"ratio","difficulty":2,"statement":"Поезд проходит мост 500 м за 1 минуту, мимо столба — за 20 секунд. Какова длина поезда?","answer":"250","solution":"L=20v, L+500=60v → v=12,5 м/с, L=250 м.","image":null},{"id":"v1_20","school":"РФМШ","variant":"v1","num":20,"topic":"ratio","difficulty":2,"statement":"Реки: 4248, 2450, 2488, 2214 км. Найдите их общую длину в см на карте масштаба 1:2 500 000.","answer":"456","solution":"Сумма 11400 км = 1,14·10^9 см. /2 500 000 = 456 см.","image":null},{"id":"v1_21","school":"РФМШ","variant":"v1","num":21,"topic":"num","difficulty":3,"statement":"Сумма двух чисел 2010. Частное от деления большего на меньшее равно 11. Чему равен остаток?","answer":"6","solution":"12b+r=2010, b=167, r=6. (Условие допускает неоднозначность — стандартный ответ 6.)","image":null},{"id":"v1_22","school":"РФМШ","variant":"v1","num":22,"topic":"spat","difficulty":2,"statement":"Сколько всего квадратов, ограниченных линиями сетки, можно найти на рисунке?","answer":"20","solution":"Сетка 3×4: 1×1 = 12, 2×2 = 6, 3×3 = 2. Всего 20.","image":"/figures/v1_q22.png"},{"id":"v1_23","school":"РФМШ","variant":"v1","num":23,"topic":"eq","difficulty":2,"statement":"Решите уравнение: (2,3x−11,2)/0,7 = (1,7x−9,4)/(−2,1).","answer":"5","solution":"Крест-накрест: −4,83x+23,52 = 1,19x−6,58 → 30,1 = 6,02x → x=5.","image":null},{"id":"v1_24","school":"РФМШ","variant":"v1","num":24,"topic":"comb","difficulty":2,"statement":"Операция a⊕b = (2a−1)(2b−1). Вычислите 2⊕(3⊕4).","answer":"207","solution":"3⊕4 = 5·7 = 35. 2⊕35 = 3·69 = 207.","image":null},{"id":"v1_25","school":"РФМШ","variant":"v1","num":25,"topic":"pct","difficulty":3,"statement":"Мандариновое дерево даёт 300 кг, апельсиновое 800 кг, в среднем 600 кг с дерева. Каков процент мандариновых деревьев?","answer":"40%","solution":"o=1,5m → m/(2,5m) = 0,4 = 40%.","image":null},{"id":"v1_26","school":"РФМШ","variant":"v1","num":26,"topic":"sys","difficulty":2,"statement":"Сколько целых решений имеет двойное неравенство 11 < |2−x| ≤ 14?","answer":"6","solution":"x−2 ∈ {12,13,14} или {−12,−13,−14} → 6 решений.","image":null},{"id":"v1_27","school":"РФМШ","variant":"v1","num":27,"topic":"eq","difficulty":3,"statement":"Четыре числа: +2 к первому, −2 от второго, ×2 третье, ÷2 четвёртое — станут равными. Сумма всех четырёх 45. Найдите первое число.","answer":"8","solution":"Общее k=10. Первое = k−2 = 8.","image":null},{"id":"v1_28","school":"РФМШ","variant":"v1","num":28,"topic":"num","difficulty":2,"statement":"Вычислите: 21 + 28 + 35 + … + 588 + 595 + 602.","answer":"26166","solution":"n=84, сумма = 84·(21+602)/2 = 26166.","image":null},{"id":"v1_29","school":"РФМШ","variant":"v1","num":29,"topic":"num","difficulty":3,"statement":"Найдите наименьшее натуральное n такое, что n! делится на 2023.","answer":"34","solution":"2023 = 7·17². Нужны два множителя 17: 17 и 34 → n=34.","image":null},{"id":"v1_30","school":"РФМШ","variant":"v1","num":30,"topic":"pct","difficulty":3,"statement":"Два шоколада с 20 г молока и 40 г воды → 180 г горячего шоколада, 42% какао. Какао в первом 70%, во втором 30%. Сколько граммов первого шоколада?","answer":"99","solution":"c1+c2=120. 0,7c1+0,3c2 = 75,6 → c1 = 99 г.","image":null},{"id":"v2_1","school":"РФМШ","variant":"v2","num":1,"topic":"eq","difficulty":1,"statement":"Найдите корень уравнения: (x+3)/65 = 4/13.","answer":"17","solution":"x+3 = 65·4/13 = 20 → x=17.","image":null},{"id":"v2_2","school":"РФМШ","variant":"v2","num":2,"topic":"num","difficulty":1,"statement":"Найдите делимое, если делитель 13, неполное частное 12, остаток 10.","answer":"166","solution":"13·12+10 = 166.","image":null},{"id":"v2_3","school":"РФМШ","variant":"v2","num":3,"topic":"work","difficulty":1,"statement":"Первая труба наполняет бассейн за 6 ч, вторая за 12 ч. За сколько часов наполнят вместе?","answer":"4","solution":"1/6+1/12 = 1/4 → 4 ч.","image":null},{"id":"v2_4","school":"РФМШ","variant":"v2","num":4,"topic":"work","difficulty":2,"statement":"На дворе куры и овцы: 35 голов и 94 ноги. Сколько кур?","answer":"23","solution":"c+s=35, 2c+4s=94 → s=12, c=23.","image":null},{"id":"v2_5","school":"РФМШ","variant":"v2","num":5,"topic":"num","difficulty":2,"statement":"Сумма шести последовательных чисел равна 441. Найдите произведение наибольшего и наименьшего.","answer":"5396","solution":"6n+15=441 → n=71. Числа 71..76. 71·76 = 5396.","image":null},{"id":"v2_6","school":"РФМШ","variant":"v2","num":6,"topic":"ratio","difficulty":1,"statement":"Первая труба на чертеже 24 см, реально 6 м. Сколько см на чертеже у трубы длиной 4,5 м?","answer":"18","solution":"Масштаб 24см/6м = 4 см/м. 4,5·4 = 18 см.","image":null},{"id":"v2_7","school":"РФМШ","variant":"v2","num":7,"topic":"geo","difficulty":2,"statement":"Длина первой окружности 13, её диаметр равен радиусу второй. Чему равна длина второй окружности?","answer":"26","solution":"C2 = 2π·(d1) = 2·(π·d1) = 2·13 = 26.","image":null},{"id":"v2_8","school":"РФМШ","variant":"v2","num":8,"topic":"frac","difficulty":2,"statement":"Упростите и найдите при m=1944: 9/10·m − 2/15·m − 3/5·m.","answer":"324","solution":"Коэффициент 1/6. 1944/6 = 324.","image":null},{"id":"v2_9","school":"РФМШ","variant":"v2","num":9,"topic":"geo","difficulty":2,"statement":"Прямые AB, CD, EF пересекаются в O, AB⊥CD, ∠AOE=35°. Найдите ∠COF.","answer":"55","solution":"∠EOC = 90−35 = 55°. ∠COF вертикален ∠DOE = 55°.","image":"/figures/v2_q9.svg"},{"id":"v2_10","school":"РФМШ","variant":"v2","num":10,"topic":"ratio","difficulty":1,"statement":"На прямой 100 точек, расстояние между соседними 7. Расстояние между крайними?","answer":"693","solution":"99·7 = 693.","image":null},{"id":"v2_11","school":"РФМШ","variant":"v2","num":11,"topic":"comb","difficulty":3,"statement":"Заяц и черепаха бегут 100 м. Когда заяц финишировал, черепахе осталось 90 м. На сколько метров отодвинуть старт зайца для ничьей?","answer":"900","solution":"Скорости 10:1. (100+x)/10=100 → x=900.","image":null},{"id":"v2_12","school":"РФМШ","variant":"v2","num":12,"topic":"num","difficulty":2,"statement":"Сколько натуральных чисел от 1 до 100 делятся на 2, но не на 3?","answer":"34","solution":"50 − 16 = 34.","image":null},{"id":"v2_13","school":"РФМШ","variant":"v2","num":13,"topic":"pct","difficulty":2,"statement":"Депозит 10% годовых. Через 2 года на счёте 60500 тг. Сколько вложили изначально?","answer":"50000","solution":"P·1,21 = 60500 → P=50000.","image":null},{"id":"v2_14","school":"РФМШ","variant":"v2","num":14,"topic":"sys","difficulty":2,"statement":"Найдите наибольшее целое решение: (1−2x)/7 − 3 < −x − (2x+3)/5.","answer":"2","solution":"39x<79 → x<2,03 → x=2.","image":null},{"id":"v2_15","school":"РФМШ","variant":"v2","num":15,"topic":"num","difficulty":2,"statement":"Найдите НОД(a,b): a=2·3·25·49·11, b=2·9·5·7·11·13.","answer":"2310","solution":"НОД = 2·3·5·7·11 = 2310.","image":null},{"id":"v2_16","school":"РФМШ","variant":"v2","num":16,"topic":"frac","difficulty":3,"statement":"Вычислите: 26·(3 − 1/4 + 2/3)·(6/13 − 7/26 + 2/52) + ((−1/8 + 1 − 3/4)·52).","answer":"27","solution":"Первая часть 20,5, вторая 6,5. Сумма 27.","image":null},{"id":"v2_17","school":"РФМШ","variant":"v2","num":17,"topic":"comb","difficulty":3,"statement":"К площади 6 улиц: 4 двусторонние, 2 односторонние (к площади). Приехать и покинуть площадь. Сколькими способами?","answer":"20","solution":"Въезд 6 способов, выезд по 4 двусторонним (разной улицей): 2·4+4·3 = 20.","image":null},{"id":"v2_18","school":"РФМШ","variant":"v2","num":18,"topic":"frac","difficulty":2,"statement":"Вычислите: −|7,14| : |−2,1| − (2,15 − |−4,3|) + (1,5 + |−4,75|).","answer":"5","solution":"−3,4 + 2,15 + 6,25 = 5.","image":null},{"id":"v2_19","school":"РФМШ","variant":"v2","num":19,"topic":"spat","difficulty":2,"statement":"Сколько всего треугольников можно найти на рисунке?","answer":null,"solution":"Подсчёт зависит от рисунка. В приложении показан чертёж — сверьте по нему.","image":"/figures/v2_q19.png"},{"id":"v2_20","school":"РФМШ","variant":"v2","num":20,"topic":"ratio","difficulty":3,"statement":"Две дороги: первая на 10 км длиннее. Первый авто 3,5 ч по первой, второй 2,5 ч по второй. Скорость первого на 20 км/ч меньше. Найдите скорость первого.","answer":"60","solution":"3,5v = 2,5(v+20)+10 → v=60 км/ч.","image":null},{"id":"v2_21","school":"РФМШ","variant":"v2","num":21,"topic":"pct","difficulty":3,"statement":"28 альбомов за 50400 тг, наценка 20%, продал 15. Остальные с доп. наценкой 10%. Найдите прибыль.","answer":"12420","solution":"Себестоимость 1800. Выручка 32400+30420=62820. Прибыль 62820−50400=12420.","image":null},{"id":"v2_22","school":"РФМШ","variant":"v2","num":22,"topic":"eq","difficulty":3,"statement":"Найдите (a+c)(b+d)/(cd), если a:b=c:d=3 и b:d=−7.","answer":"36","solution":"a=−21d, c=3d, b=−7d. (−18d)(−6d)/(3d²)=36.","image":null},{"id":"v2_23","school":"РФМШ","variant":"v2","num":23,"topic":"num","difficulty":2,"statement":"Разность суммы первых 50 натуральных чисел и суммы первых 25 нечётных чисел.","answer":"650","solution":"1275 − 625 = 650.","image":null},{"id":"v2_24","school":"РФМШ","variant":"v2","num":24,"topic":"geo","difficulty":2,"statement":"A(−3), B(15), C между ними, AC=8·BC. Найдите координату C.","answer":"13","solution":"9BC=18 → BC=2, AC=16. C=−3+16=13.","image":null},{"id":"v2_25","school":"РФМШ","variant":"v2","num":25,"topic":"num","difficulty":2,"statement":"Сумма всех натуральных n, при которых 24/(n+4) — целое число.","answer":"34","solution":"n+4 ∈ {6,8,12,24} → n=2,4,8,20. Сумма 34.","image":null},{"id":"v2_26","school":"РФМШ","variant":"v2","num":26,"topic":"geo","difficulty":2,"statement":"В окружность радиусом 20 вписан квадрат. Найдите сумму площадей закрашенных частей (π=3,14).","answer":"456","solution":"Круг 1256, квадрат 800. 1256−800 = 456.","image":"/figures/v2_q26.svg"},{"id":"v2_27","school":"РФМШ","variant":"v2","num":27,"topic":"sys","difficulty":2,"statement":"Найдите сумму всех целых решений: 2 < |x/2 − 3| ≤ 5.","answer":"72","solution":"x=11..16 (сумма 81) и x=−4..1 (сумма −9). Итого 72.","image":null},{"id":"v2_28","school":"РФМШ","variant":"v2","num":28,"topic":"ratio","difficulty":2,"statement":"Шёл время t со скоростью 4 км/ч, потом 2t со скоростью 7 км/ч. Средняя скорость?","answer":"6","solution":"(4t+14t)/(3t) = 18/3 = 6 км/ч.","image":null},{"id":"v2_29","school":"РФМШ","variant":"v2","num":29,"topic":"num","difficulty":3,"statement":"Наименьшее натуральное n такое, что n² делится на 2024.","answer":"1012","solution":"2024=2³·11·23. n=2²·11·23 = 1012.","image":null},{"id":"v2_30","school":"РФМШ","variant":"v2","num":30,"topic":"ratio","difficulty":3,"statement":"B на 160 км ниже A по реке (течение 4 км/ч). Из B плот и моторная лодка (20 км/ч) к A; достигнув A, лодка поворачивает. Через сколько часов догонит плот?","answer":"20","solution":"До A: 160/16=10 ч. Далее 24(t−10)=160+4t → t=20 ч.","image":null},{"id":"v3_1","school":"РФМШ","variant":"v3","num":1,"topic":"ratio","difficulty":1,"statement":"Отношение двух чисел 3:4, сумма 21. Найдите большее.","answer":"12","solution":"21/7=3, большее 4·3=12.","image":null},{"id":"v3_2","school":"РФМШ","variant":"v3","num":2,"topic":"frac","difficulty":2,"statement":"Вычислите: (3 1/5 + 2 1/4) : 1/5 − 24 3/4 + 10,5.","answer":"13","solution":"(16/5+9/4)·5 = 27,25. 27,25−24,75+10,5 = 13.","image":null},{"id":"v3_3","school":"РФМШ","variant":"v3","num":3,"topic":"num","difficulty":1,"statement":"Найдите НОК чисел 225 и 180.","answer":"900","solution":"2²·3²·5² = 900.","image":null},{"id":"v3_4","school":"РФМШ","variant":"v3","num":4,"topic":"frac","difficulty":2,"statement":"Вычислите: (|3−4| − |6−8|·|3−5|)·(1 − |2−5|).","answer":"6","solution":"(1−4)·(1−3) = (−3)(−2) = 6.","image":null},{"id":"v3_5","school":"РФМШ","variant":"v3","num":5,"topic":"seq","difficulty":2,"statement":"Ряд 1,2,2,3,3,3,4,4,4,4,… (число k повторяется k раз). На каком месте последний раз встречается 10?","answer":"55","solution":"1+2+…+10 = 55.","image":null},{"id":"v3_6","school":"РФМШ","variant":"v3","num":6,"topic":"num","difficulty":2,"statement":"При делении числа на 17 и 15 частные одинаковы; на 15 остаток 8, на 17 делится без остатка. Найдите число.","answer":"68","solution":"17q = 15q+8 → q=4, число 68.","image":null},{"id":"v3_7","school":"РФМШ","variant":"v3","num":7,"topic":"geo","difficulty":1,"statement":"Две прямые пересекаются, сумма трёх из четырёх углов 227°. Чему равен четвёртый?","answer":"133","solution":"360−227 = 133°.","image":null},{"id":"v3_8","school":"РФМШ","variant":"v3","num":8,"topic":"frac","difficulty":1,"statement":"Скольким минутам равна 5/144 часть суток?","answer":"50","solution":"1440·5/144 = 50 мин.","image":null},{"id":"v3_9","school":"РФМШ","variant":"v3","num":9,"topic":"geo","difficulty":1,"statement":"Вычислите x, если точки A, O, D на одной прямой (углы 4x°+30° и 2x°).","answer":"25","solution":"4x+30+2x=180 → 6x=150 → x=25.","image":"/figures/v3_q9.svg"},{"id":"v3_10","school":"РФМШ","variant":"v3","num":10,"topic":"eq","difficulty":2,"statement":"При каком a число x=−3 является корнем уравнения (2a−1)(|x|−2)=5?","answer":"3","solution":"(2a−1)·1=5 → a=3.","image":null},{"id":"v3_11","school":"РФМШ","variant":"v3","num":11,"topic":"geo","difficulty":1,"statement":"Периметр прямоугольника, если его площадь 140 см², а длина 70 см?","answer":"144","solution":"Ширина 2. P=2(70+2)=144.","image":null},{"id":"v3_12","school":"РФМШ","variant":"v3","num":12,"topic":"eq","difficulty":3,"statement":"Найдите корень уравнения: 2 − 5/(2 − 3/(4−x)) = 7.","answer":"3","solution":"2−3/(4−x)=−1 → 4−x=1 → x=3.","image":null},{"id":"v3_13","school":"РФМШ","variant":"v3","num":13,"topic":"geo","difficulty":2,"statement":"Точки A,B,C,D последовательно, A=15, B=23, |AB|=2|BC|, |BC|=2|CD|. Найдите координату D.","answer":"29","solution":"BC=4, CD=2. C=27, D=29.","image":"/figures/v3_q13.svg"},{"id":"v3_14","school":"РФМШ","variant":"v3","num":14,"topic":"sys","difficulty":2,"statement":"Всего 64 студента, 4 не в организациях. Части диаграммы: x+6, 2x, 3x−12. Сколько в обеих организациях?","answer":"22","solution":"6x−2=64 → x=11. Обе = 2x = 22.","image":"/figures/v3_q14.svg"},{"id":"v3_15","school":"РФМШ","variant":"v3","num":15,"topic":"pct","difficulty":2,"statement":"Цену повысили на 10%, затем на 20%. На сколько процентов выросла первоначальная цена?","answer":"32%","solution":"1,1·1,2 = 1,32 → 32%.","image":null},{"id":"v3_16","school":"РФМШ","variant":"v3","num":16,"topic":"num","difficulty":2,"statement":"Двузначное число на 45 меньше числа с теми же цифрами наоборот, сумма цифр 11. Найдите произведение цифр.","answer":"24","solution":"b−a=5, a+b=11 → 38. 3·8=24.","image":null},{"id":"v3_17","school":"РФМШ","variant":"v3","num":17,"topic":"num","difficulty":2,"statement":"В таблице 10×10 закрашены все клетки пяти строк и трёх столбцов. Сколько клеток остались незакрашенными?","answer":"35","solution":"Закрашено 50+30−15=65. Осталось 35.","image":null},{"id":"v3_18","school":"РФМШ","variant":"v3","num":18,"topic":"work","difficulty":2,"statement":"Полный бидон молока 30 кг, наполовину 18 кг. Сколько весит бидон, заполненный на четверть?","answer":"12","solution":"Молоко 24, бидон 6. 6+6 = 12 кг.","image":null},{"id":"v3_19","school":"РФМШ","variant":"v3","num":19,"topic":"ratio","difficulty":2,"statement":"Собака 2700 м за 5 мин, заяц 1060 м за 2 мин, заяц в 300 м впереди. За сколько минут собака догонит?","answer":"30","solution":"540−530 = 10 м/мин. 300/10 = 30 мин.","image":null},{"id":"v3_20","school":"РФМШ","variant":"v3","num":20,"topic":"frac","difficulty":3,"statement":"1-й месяц 3/11 плана, 2-й 1/4 остатка, 3-й остальное. 1-й на 10 машин больше 2-го. Сколько за 3-й месяц?","answer":"60","solution":"План 110. 3-й = 6/11·110 = 60.","image":null},{"id":"v3_21","school":"РФМШ","variant":"v3","num":21,"topic":"sys","difficulty":2,"statement":"Наименьшее целое решение: 0,8(2x−3) − 0,2(2x−5) > 14,5.","answer":"14","solution":"1,2x > 15,9 → x>13,25 → 14.","image":null},{"id":"v3_22","school":"РФМШ","variant":"v3","num":22,"topic":"num","difficulty":3,"statement":"Процент сдавших экзамен в интервале 96,8%–97,6%. Наименьшее возможное число учеников?","answer":"32","solution":"(n−1)/n ≥ 0,968 → n≥32. 31/32 = 96,875%.","image":null},{"id":"v3_23","school":"РФМШ","variant":"v3","num":23,"topic":"comb","difficulty":2,"statement":"Сколько пятизначных чисел, делящихся на 3, можно составить из цифр 1,2,3,4,5 ровно по разу?","answer":"120","solution":"Сумма цифр 15 делится на 3 → все 5! = 120.","image":null},{"id":"v3_24","school":"РФМШ","variant":"v3","num":24,"topic":"num","difficulty":3,"statement":"На доске 1..8. Стирают a,b и пишут ab/2. Осталось одно число. Чему оно равно?","answer":"315","solution":"Каждая операция делит произведение на 2. 8!/2^7 = 40320/128 = 315.","image":null},{"id":"v3_25","school":"РФМШ","variant":"v3","num":25,"topic":"work","difficulty":3,"statement":"Двое вместе за 30 дней. После 6 дней вместе первый один заканчивает за 40 дней. За сколько дней второй один?","answer":"75","solution":"Первый 1/50, второй 1/30−1/50 = 1/75 → 75 дней.","image":null},{"id":"v3_26","school":"РФМШ","variant":"v3","num":26,"topic":"num","difficulty":1,"statement":"Десять последовательных целых. На сколько сумма пяти наибольших больше суммы пяти наименьших?","answer":"25","solution":"Каждая пара отличается на 5. 5·5 = 25.","image":null},{"id":"v3_27","school":"РФМШ","variant":"v3","num":27,"topic":"work","difficulty":3,"statement":"Бассейн из двух труб за 7,5 ч. Отношение времени первой к второй 3:5. За сколько наполнит только вторая?","answer":"20","solution":"t1=3k, t2=5k. 8/(15k)=1/7,5 → k=4, t2=20 ч.","image":null},{"id":"v3_28","school":"РФМШ","variant":"v3","num":28,"topic":"ratio","difficulty":3,"statement":"Пройдя половину, бегун увеличил скорость на 25% и прибыл на 0,5 ч раньше. Сколько минут на весь маршрут?","answer":"270","solution":"d/v=2,5 ч. Факт 1,8·2,5 = 4,5 ч = 270 мин.","image":null},{"id":"v3_29","school":"РФМШ","variant":"v3","num":29,"topic":"comb","difficulty":3,"statement":"Три бегуна 100 м. Арман финишировал — Бауыржан отставал 10 м. Бауыржан финишировал — Саят отставал 10 м. На сколько отставал Саят от Армана?","answer":"19","solution":"Саят = 90·0,9 = 81. Отставание 100−81 = 19 м.","image":null},{"id":"v3_30","school":"РФМШ","variant":"v3","num":30,"topic":"sys","difficulty":2,"statement":"Сколько целых решений имеет неравенство ||2x−3|−4| ≤ 5?","answer":"10","solution":"|2x−3|≤9 → −3≤x≤6 → 10 целых.","image":null},{"id":"v4_1","school":"РФМШ","variant":"v4","num":1,"topic":"eq","difficulty":1,"statement":"Найдите корень уравнения: 3(5−x)+13 = 4(3x−8).","answer":"4","solution":"28−3x = 12x−32 → 15x=60 → x=4.","image":null},{"id":"v4_2","school":"РФМШ","variant":"v4","num":2,"topic":"geo","difficulty":1,"statement":"Длину прямоугольника увеличили в 2 раза, ширину в 3 раза. Во сколько раз увеличилась площадь?","answer":"6","solution":"2·3 = 6.","image":null},{"id":"v4_3","school":"РФМШ","variant":"v4","num":3,"topic":"work","difficulty":1,"statement":"Сумма нескольких целых положительных чисел равна 72, их среднее 12. Сколько было чисел?","answer":"6","solution":"72/12 = 6.","image":null},{"id":"v4_4","school":"РФМШ","variant":"v4","num":4,"topic":"sys","difficulty":2,"statement":"25 туристов: 12 хотят Байтерек, 19 — Астана Опера, все хотят хотя бы один объект. Сколько хотят и то, и другое?","answer":"6","solution":"12+19−25 = 6.","image":null},{"id":"v4_5","school":"РФМШ","variant":"v4","num":5,"topic":"geo","difficulty":1,"statement":"На сколько градусов поворачивается часовая стрелка за 2,5 часа?","answer":"75","solution":"30·2,5 = 75°.","image":null},{"id":"v4_6","school":"РФМШ","variant":"v4","num":6,"topic":"pct","difficulty":1,"statement":"Сколько получится, если к 35% числа 300 прибавить 15% числа 200?","answer":"135","solution":"105+30 = 135.","image":null},{"id":"v4_7","school":"РФМШ","variant":"v4","num":7,"topic":"work","difficulty":2,"statement":"У кур и кроликов 15 голов и 44 ноги. Сколько кроликов?","answer":"7","solution":"2r=14 → r=7.","image":null},{"id":"v4_8","school":"РФМШ","variant":"v4","num":8,"topic":"frac","difficulty":2,"statement":"Найдите число, обратное произведению чисел 6 1/4 и 1/25.","answer":"4","solution":"25/4·1/25 = 1/4. Обратное = 4.","image":null},{"id":"v4_9","school":"РФМШ","variant":"v4","num":9,"topic":"num","difficulty":3,"statement":"В семье 4 несовершеннолетних. Трое на 2, 6, 8 лет старше младшего, возраст каждого — простое число. Сколько лет старшему?","answer":"13","solution":"p=5: 5,7,11,13 — все простые. Старший 13.","image":null},{"id":"v4_10","school":"РФМШ","variant":"v4","num":10,"topic":"frac","difficulty":2,"statement":"Снегурочка съела 3/5 мандарина, осталось 1 1/3 кг. Сколько кг съела?","answer":"2","solution":"Остаток 2/5 = 4/3 → всего 10/3. Съела 3/5·10/3 = 2 кг.","image":null},{"id":"v4_11","school":"РФМШ","variant":"v4","num":11,"topic":"frac","difficulty":3,"statement":"Вычислите: (1 + 1/(2+1:(3−1:4)))·26.","answer":"37","solution":"Внутри 37/26. ·26 = 37.","image":null},{"id":"v4_12","school":"РФМШ","variant":"v4","num":12,"topic":"work","difficulty":1,"statement":"Две кошки за две минуты поймали двух мышей. За сколько минут три кошки поймают трёх мышей?","answer":"2","solution":"1 кошка ловит 1 мышь за 2 мин → 3 кошки 3 мыши за 2 мин.","image":null},{"id":"v4_13","school":"РФМШ","variant":"v4","num":13,"topic":"pct","difficulty":2,"statement":"Когда бочка пуста на 40%, в ней на 30 л больше воды, чем когда полна на 20%. Сколько литров в полной бочке?","answer":"75","solution":"60%V − 20%V = 40%V = 30 → V=75.","image":null},{"id":"v4_14","school":"РФМШ","variant":"v4","num":14,"topic":"eq","difficulty":3,"statement":"Найдите корень уравнения: 30/(1 + 10/(3 − 7/(4 + x/2))) − 4,5 = 0,5.","answer":"6","solution":"Раскручиваем: 4+x/2 = 7 → x=6.","image":null},{"id":"v4_15","school":"РФМШ","variant":"v4","num":15,"topic":"geo","difficulty":2,"statement":"Периметр четырёхугольника 420 см. Первая сторона равна среднему арифметическому остальных трёх. Найдите первую сторону.","answer":"105","solution":"a=S/3, a+S=420 → 4a=420 → a=105.","image":null},{"id":"v4_16","school":"РФМШ","variant":"v4","num":16,"topic":"ratio","difficulty":3,"statement":"Четыре числа по возрастанию, отношение последних трёх 2:5:6. Наибольшее больше первого на 17, сумма всех 40. Найдите второе число.","answer":"6","solution":"k=3: числа 1,6,15,18. Второе = 6.","image":null},{"id":"v4_17","school":"РФМШ","variant":"v4","num":17,"topic":"pct","difficulty":2,"statement":"Цену телефона понизили на 30%, затем повысили на 20% — стал 16800 тг. Сколько стоил изначально?","answer":"20000","solution":"0,84·P = 16800 → P=20000.","image":null},{"id":"v4_18","school":"РФМШ","variant":"v4","num":18,"topic":"ratio","difficulty":3,"statement":"В сникерсе орех:сахар = 5:2, сахар:шоколад = 3:11. Шоколада на 32 г больше сахара. Сколько весит сникерс?","answer":"86","solution":"Орех:сахар:шоколад = 15:6:22. 16 частей = 32 г → 1 часть 2 г. 43·2 = 86 г.","image":null},{"id":"v4_19","school":"РФМШ","variant":"v4","num":19,"topic":"pct","difficulty":3,"statement":"Стороны прямоугольника 2:3. Короткую увеличили на 20%, длинную на 25%. На сколько % вырос периметр?","answer":"23%","solution":"Стороны 2,4 и 3,75. P: 10 → 12,3 → +23%.","image":null},{"id":"v4_20","school":"РФМШ","variant":"v4","num":20,"topic":"spat","difficulty":2,"statement":"Найдите площадь фигуры на клетчатой бумаге с размером клетки 1×1.","answer":null,"solution":"Площадь считается по фигуре (можно формулой Пика). В приложении показан рисунок — сверьте по нему.","image":"/figures/v4_q20.png"},{"id":"v4_21","school":"РФМШ","variant":"v4","num":21,"topic":"eq","difficulty":2,"statement":"Найдите корень уравнения: 6 : ((8 + 3x/5)/x + 9) = 3/5.","answer":"20","solution":"(8+3x/5)/x = 1 → 8 = 2x/5 → x=20.","image":null},{"id":"v4_22","school":"РФМШ","variant":"v4","num":22,"topic":"geo","difficulty":2,"statement":"Найдите произведение всех x, при которых расстояние между A(3x+5) и B(2x) равно 3.","answer":"16","solution":"|x+5|=3 → x=−2 или −8. Произведение 16.","image":null},{"id":"v4_23","school":"РФМШ","variant":"v4","num":23,"topic":"ratio","difficulty":3,"statement":"За 4 ч по течению катер проходит в 2,4 раза больше, чем за 2 ч против. Скорость течения 1,5 км/ч. Сколько км за 10 ч в стоячей воде?","answer":"165","solution":"4(v+1,5)=4,8(v−1,5) → v=16,5. 16,5·10 = 165 км.","image":null},{"id":"v4_24","school":"РФМШ","variant":"v4","num":24,"topic":"geo","difficulty":3,"statement":"Сторона квадрата 80. Закрашенная фигура ограничена двумя четвертями дуг радиусом = стороне. Найдите её площадь (π=3,14).","answer":"3648","solution":"(π/2 − 1)·80² = 0,57·6400 = 3648.","image":"/figures/v4_q24.svg"},{"id":"v4_25","school":"РФМШ","variant":"v4","num":25,"topic":"num","difficulty":2,"statement":"Вычислите: 11,2 + 12,2 + 13,2 + … + 99,2 + 100,2.","answer":"5013","solution":"90 членов. 90·(11,2+100,2)/2 = 5013.","image":null},{"id":"v4_26","school":"РФМШ","variant":"v4","num":26,"topic":"comb","difficulty":2,"statement":"Из цифр 3,7,4,1,8 составили пятизначные числа без повторений. Сколько среди них чётных?","answer":"48","solution":"Последняя цифра 4 или 8 (2), остальные 4! = 24. 2·24 = 48.","image":null},{"id":"v4_27","school":"РФМШ","variant":"v4","num":27,"topic":"geo","difficulty":2,"statement":"Часы показывают 10 часов 34 минуты. Найдите угол между стрелками (меньший 180°).","answer":"113","solution":"|317 − 204| = 113°.","image":null},{"id":"v4_28","school":"РФМШ","variant":"v4","num":28,"topic":"eq","difficulty":2,"statement":"Найдите сумму корней уравнения: |x−6|/10 : 6/7 = 1 1/6 : 3 1/3.","answer":"12","solution":"|x−6|=3 → x=9 или 3. Сумма 12.","image":null},{"id":"v4_29","school":"РФМШ","variant":"v4","num":29,"topic":"sys","difficulty":2,"statement":"Найдите наибольшее целое решение: 3x/4 − 5/6 < (3x+5)/6 − x/3.","answer":"2","solution":"7x<20 → x<2,86 → x=2.","image":null},{"id":"v4_30","school":"РФМШ","variant":"v4","num":30,"topic":"geo","difficulty":2,"statement":"Точки A(x;2) и B(7;y) симметричны относительно C(4;3). Найдите x+y.","answer":"5","solution":"x=1, y=4 → x+y=5.","image":null},{"id":"v5_1","school":"РФМШ","variant":"v5","num":1,"topic":"comb","difficulty":2,"statement":"Арман, Болат, Азамат, Саян заняли первые 4 места. Трое ответили: 1) Арман ни первый, ни четвёртый; 2) Болат третий; 3) Азамат не был первым. Какое место занял Саян?","answer":"1","solution":"Болат 3-й, Арман 2-й, Азамат не 1-й → 4-й, Саян 1-й.","image":null},{"id":"v5_2","school":"РФМШ","variant":"v5","num":2,"topic":"frac","difficulty":2,"statement":"Вычислите (7x+14y+21z)/(4z+2y−x), если x:y:z = 3:1:2.","answer":"11","solution":"x=3,y=1,z=2: 77/7 = 11.","image":null},{"id":"v5_3","school":"РФМШ","variant":"v5","num":3,"topic":"frac","difficulty":2,"statement":"Вычислите: (12 ч 5 мин 21 сек − 11 ч 32 мин 5 сек + 2 ч 1 мин 44 сек) / 1 мин.","answer":"155","solution":"Итог 2 ч 35 мин = 155 мин. /1 мин = 155.","image":null},{"id":"v5_4","school":"РФМШ","variant":"v5","num":4,"topic":"num","difficulty":1,"statement":"Вычислите: НОД(15,30)·НОД(12,16).","answer":"60","solution":"15·4 = 60.","image":null},{"id":"v5_5","school":"РФМШ","variant":"v5","num":5,"topic":"eq","difficulty":2,"statement":"Найдите значение: 5(3x−3y−7) − 6(3x−2y−5) + 3(x+y+4).","answer":"7","solution":"x и y сокращаются, остаётся −35+30+12 = 7.","image":null},{"id":"v5_6","school":"РФМШ","variant":"v5","num":6,"topic":"ratio","difficulty":2,"statement":"Расстояние 162 км, навстречу два велосипедиста 13 и 14 км/ч. Через сколько часов расстояние между ними впервые 27 км?","answer":"5","solution":"(162−27)/27 = 5 ч.","image":null},{"id":"v5_7","school":"РФМШ","variant":"v5","num":7,"topic":"seq","difficulty":2,"statement":"Найдите число вместо вопросительного знака (по закономерности рисунка).","answer":"8","solution":"Центр = левое − верхнее. Для третьей ячейки 13 − 5 = 8.","image":"/figures/v5_q7.svg"},{"id":"v5_8","school":"РФМШ","variant":"v5","num":8,"topic":"frac","difficulty":1,"statement":"Вычислите: |34,2| : |−1,9| + (5,55 − |−3,3|) − 0,25.","answer":"20","solution":"18 + 2,25 − 0,25 = 20.","image":null},{"id":"v5_9","school":"РФМШ","variant":"v5","num":9,"topic":"geo","difficulty":1,"statement":"За сколько минут часовая стрелка поворачивается на 38 градусов?","answer":"76","solution":"38 / 0,5 = 76 мин.","image":null},{"id":"v5_10","school":"РФМШ","variant":"v5","num":10,"topic":"ratio","difficulty":2,"statement":"584 кг апельсинов в 3 магазина. Первый:второй = 3:2, третий на 15% больше второго. Сколько в третий?","answer":"184","solution":"7,3k=584 → k=80. Третий 2,3·80 = 184.","image":null},{"id":"v5_11","school":"РФМШ","variant":"v5","num":11,"topic":"num","difficulty":2,"statement":"В классе менее 50. 1/6 получили «5», 1/7 «4», 1/2 «3», остальные «2». Сколько «2»?","answer":"8","solution":"Класс 42. 7+6+21=34. «2»: 42−34 = 8.","image":null},{"id":"v5_12","school":"РФМШ","variant":"v5","num":12,"topic":"eq","difficulty":2,"statement":"Решите уравнение: (4x+1)/3 − x = (3x−2)/2 − (x+2)/4.","answer":"2","solution":"4x+4 = 15x−18 → x=2.","image":null},{"id":"v5_13","school":"РФМШ","variant":"v5","num":13,"topic":"comb","difficulty":3,"statement":"Шахматист 40 партий, 26 очков (победа 1, ничья 0,5, поражение 0). Разница числа побед и поражений?","answer":"12","solution":"2w+d=52, w−l = 2w+d−40 = 12.","image":null},{"id":"v5_14","school":"РФМШ","variant":"v5","num":14,"topic":"work","difficulty":3,"statement":"Три каменщика — стену за 3 ч. Первый один за 5 ч, второй за 18 ч 45 мин. За сколько минут третий один?","answer":"750","solution":"1/3 − 1/5 − 4/75 = 2/25 → 12,5 ч = 750 мин.","image":null},{"id":"v5_15","school":"РФМШ","variant":"v5","num":15,"topic":"frac","difficulty":3,"statement":"Вычислите: (162,162:2,25 + 0,828):0,0125 / (5,1·5,1 + 10,2·3,9 + 3,9·3,9).","answer":"72","solution":"Числитель 5832, знаменатель (5,1+3,9)²=81. 5832/81 = 72.","image":null},{"id":"v5_16","school":"РФМШ","variant":"v5","num":16,"topic":"ratio","difficulty":2,"statement":"Асан круг за 8 мин, Марат за 10 мин, едут в одну сторону. Через сколько минут Асан догонит Марата?","answer":"40","solution":"t(1/8−1/10)=1 → t=40 мин.","image":null},{"id":"v5_17","school":"РФМШ","variant":"v5","num":17,"topic":"eq","difficulty":2,"statement":"Найдите произведение корней уравнения |3x+12| = |−x|.","answer":"18","solution":"x=−6 и x=−3. Произведение 18.","image":null},{"id":"v5_18","school":"РФМШ","variant":"v5","num":18,"topic":"sys","difficulty":2,"statement":"Найдите наименьшее целое решение: (1−x)/2 + 3 < 3x − (2x+1)/7.","answer":"2","solution":"51 < 45x → x>1,13 → x=2.","image":null},{"id":"v5_19","school":"РФМШ","variant":"v5","num":19,"topic":"num","difficulty":3,"statement":"Страницы пронумерованы с 1. Из середины вырван двойной листочек, сумма четырёх номеров 130. Какой номер у последней страницы тетради?","answer":"64","solution":"Пажи 31,32,33,34 (сумма 130) — центральные. Всего 64 страницы.","image":null},{"id":"v5_20","school":"РФМШ","variant":"v5","num":20,"topic":"num","difficulty":2,"statement":"Сумма всех натуральных n, при которых 80/(n+10) — натуральное число.","answer":"116","solution":"n+10 ∈ {16,20,40,80} → n=6,10,30,70. Сумма 116.","image":null},{"id":"v5_21","school":"РФМШ","variant":"v5","num":21,"topic":"comb","difficulty":3,"statement":"Каждый звонок: 3 детей в маленькую аудиторию, половину оставшихся в большую. После 4-го звонка осталось 8. Сколько было до первого звонка?","answer":"173","solution":"Обратно: a=2·next+3. 8→19→41→85→173.","image":null},{"id":"v5_22","school":"РФМШ","variant":"v5","num":22,"topic":"sys","difficulty":2,"statement":"4≤a≤5, 5≤b≤6. Сумма всех целых значений выражения 2a−b?","answer":"14","solution":"2a−b ∈ [2,5]. Целые 2,3,4,5. Сумма 14.","image":null},{"id":"v5_23","school":"РФМШ","variant":"v5","num":23,"topic":"sys","difficulty":1,"statement":"Найдите сумму всех целых решений неравенства |3x−17| < 5.","answer":"18","solution":"4<x<7,33 → x=5,6,7. Сумма 18.","image":null},{"id":"v5_24","school":"РФМШ","variant":"v5","num":24,"topic":"num","difficulty":3,"statement":"Вычислите: 1/3 + 2/3 − 3/3 + 4/3 + 5/3 − 6/3 + … + 106/3 + 107/3 − 108/3.","answer":"630","solution":"Группа даёт k−1, 36 групп: Σ0..35 = 630.","image":null},{"id":"v5_25","school":"РФМШ","variant":"v5","num":25,"topic":"pct","difficulty":3,"statement":"Из 30 кг свежих яблок 4,8 кг сушёных (40% воды). Сколько г воды в 1000 г свежих яблок?","answer":"904","solution":"Сухого вещества 2,88 кг. Вода в свежих 27,12/30 = 0,904 → 904 г.","image":null},{"id":"v5_26","school":"РФМШ","variant":"v5","num":26,"topic":"geo","difficulty":2,"statement":"На AC точка B. Полуокружности на AC и AB равны 12,56 см и 3,14 см. Чему равен отрезок BC? (π=3,14)","answer":"6","solution":"AC=8, AB=2 → BC=6.","image":"/figures/v5_q26.svg"},{"id":"v5_27","school":"РФМШ","variant":"v5","num":27,"topic":"ratio","difficulty":2,"statement":"Из A в B (23 км) пешеход 4 км/ч. Через 12 мин из B навстречу велосипедист 14 км/ч. Через сколько минут после выезда велосипедиста встретятся?","answer":"74","solution":"Пешеход прошёл 0,8 км. (23−0,8)/18 = 1,233 ч = 74 мин.","image":null},{"id":"v5_28","school":"РФМШ","variant":"v5","num":28,"topic":"geo","difficulty":2,"statement":"Из 6 равносторонних треугольников составили фигуру. Стороны треугольников 1–6: 9,12,14,9,15,11 см. Чему равен периметр фигуры?","answer":null,"solution":"Периметр зависит от того, какие стороны внешние — в приложении показан рисунок, сверьте по нему.","image":"/figures/v5_q28.png"},{"id":"v5_29","school":"РФМШ","variant":"v5","num":29,"topic":"geo","difficulty":2,"statement":"Масштаб 1:100 000, лес прямоугольный 30 мм и 80 мм. Сколько гектаров?","answer":"2400","solution":"Реально 3 км × 8 км = 24 км² = 2400 га.","image":null},{"id":"v5_30","school":"РФМШ","variant":"v5","num":30,"topic":"ratio","difficulty":3,"statement":"Первую четверть пути авто 84 км/ч, остальное 42 км/ч. Средняя скорость на всём пути?","answer":"48","solution":"Время d/12, путь 4d → 48 км/ч.","image":null},{"id":"v7_1","school":"РФМШ","variant":"v7","num":1,"topic":"geo","difficulty":2,"statement":"Длина прямоугольного параллелепипеда 4. Ширина в 6 раз больше длины, высота в 3 раза меньше ширины. Найдите объём.","answer":"768","solution":"4·24·8 = 768.","image":null},{"id":"v7_2","school":"РФМШ","variant":"v7","num":2,"topic":"work","difficulty":1,"statement":"4 рабочих выполнили задание за 14 дней. Сколько рабочих нужно, чтобы выполнить за 8 дней?","answer":"7","solution":"4·14/8 = 7.","image":null},{"id":"v7_3","school":"РФМШ","variant":"v7","num":3,"topic":"eq","difficulty":2,"statement":"Мурат в 3 раза старше Дамира, через 17 лет — в 2 раза. Сколько лет будет Дамиру через 17 лет?","answer":"34","solution":"d=17. Через 17 лет 17+17 = 34.","image":null},{"id":"v7_4","school":"РФМШ","variant":"v7","num":4,"topic":"ratio","difficulty":2,"statement":"x+y+z=85, x:y=4:7, y:z=7:6. Найдите z.","answer":"30","solution":"x:y:z = 4:7:6, 85/17=5, z=30.","image":null},{"id":"v7_5","school":"РФМШ","variant":"v7","num":5,"topic":"work","difficulty":1,"statement":"На доске 11 чисел, среднее 7. Какое 12-е число дописать, чтобы среднее 12 чисел тоже 7?","answer":"7","solution":"84 − 77 = 7.","image":null},{"id":"v7_6","school":"РФМШ","variant":"v7","num":6,"topic":"frac","difficulty":3,"statement":"Вычислите: (3 1/3·1,9 + 19,5:4 1/2)/(62/75 − 0,16).","answer":"16","solution":"(32/3)/(2/3) = 16.","image":null},{"id":"v7_7","school":"РФМШ","variant":"v7","num":7,"topic":"geo","difficulty":2,"statement":"Длина окружности 251,2. Найдите площадь круга (π=3,14).","answer":"5024","solution":"r=40. S=3,14·1600 = 5024.","image":null},{"id":"v7_8","school":"РФМШ","variant":"v7","num":8,"topic":"comb","difficulty":2,"statement":"Если по 6 конфет — 7 останется, если по 7 — не хватит 6. Сколько детей?","answer":"13","solution":"6n+7 = 7n−6 → n=13.","image":null},{"id":"v7_9","school":"РФМШ","variant":"v7","num":9,"topic":"work","difficulty":1,"statement":"Среднее 4 чисел 13, среднее 2 других 19. Найдите среднее всех шести.","answer":"15","solution":"(52+38)/6 = 15.","image":null},{"id":"v7_10","school":"РФМШ","variant":"v7","num":10,"topic":"sys","difficulty":2,"statement":"17 любят мультфильмы, 14 детективы, 3 — и то, и другое, 3 — ни то ни другое. Сколько учеников в классе?","answer":"31","solution":"(17+14−3)+3 = 31.","image":null},{"id":"v7_11","school":"РФМШ","variant":"v7","num":11,"topic":"comb","difficulty":2,"statement":"15 белых и 12 красных шаров. Асан вытащил 17. Наименьшее число красных среди них?","answer":"2","solution":"Худший случай: 15 белых + 2 красных = 17.","image":null},{"id":"v7_12","school":"РФМШ","variant":"v7","num":12,"topic":"geo","difficulty":2,"statement":"Общая часть двух прямоугольников закрашена. Незакрашенная часть прямоугольника a×b равна 43. Найдите незакрашенную часть c×d, если a=9,b=12,c=15,d=10.","answer":"85","solution":"Наложение = 108−43 = 65. c·d − 65 = 150−65 = 85.","image":"/figures/v7_q12.svg"},{"id":"v7_13","school":"РФМШ","variant":"v7","num":13,"topic":"num","difficulty":2,"statement":"Сумма двух натуральных 208. При делении большего на меньшее частное 3, остаток 36. Чему равно большее?","answer":"165","solution":"4b=172 → b=43, a=165.","image":null},{"id":"v7_14","school":"РФМШ","variant":"v7","num":14,"topic":"sys","difficulty":2,"statement":"120 студентов: 101 ноутбук, 86 планшет, 13 ни то ни другое. У скольких и ноутбук, и планшет?","answer":"80","solution":"107 = 101+86−x → x=80.","image":null},{"id":"v7_15","school":"РФМШ","variant":"v7","num":15,"topic":"num","difficulty":3,"statement":"В восьмизначном числе, кратном 45, заменили 2 цифры звёздочками: 154461**. Наибольшая сумма замененных цифр?","answer":"6","solution":"Кратно 5 → b∈{0,5}. Кратно 9 → a+b∈{6,15}, 15 невозможно. Макс сумма 6.","image":null},{"id":"v7_16","school":"РФМШ","variant":"v7","num":16,"topic":"eq","difficulty":2,"statement":"Операция a⊕b = 2ab − b. Найдите корень уравнения 1⊕(2⊕x) = 111.","answer":"37","solution":"2⊕x=3x, 1⊕3x=3x=111 → x=37.","image":null},{"id":"v7_17","school":"РФМШ","variant":"v7","num":17,"topic":"frac","difficulty":3,"statement":"Продали 2/7 тетрадей, затем 2/3 остатка, затем ещё 56. Осталось 4/21 всех. Сколько было?","answer":"1176","solution":"1/21 T = 56 → T=1176.","image":null},{"id":"v7_18","school":"РФМШ","variant":"v7","num":18,"topic":"num","difficulty":2,"statement":"У каких натуральных чисел от 1 до 10 нечётное количество делителей?","answer":"1, 4, 9","solution":"Нечётное число делителей — только у точных квадратов: 1, 4, 9.","image":null},{"id":"v7_19","school":"РФМШ","variant":"v7","num":19,"topic":"comb","difficulty":3,"statement":"100 человек, лжецы и правдивые, у каждого одно любимое время года. На вопросы про зиму/весну/лето/осень «да» ответили 45,50,50,55. Сколько лжецов?","answer":"50","solution":"t+3l=200, t+l=100 → l=50.","image":null},{"id":"v7_20","school":"РФМШ","variant":"v7","num":20,"topic":"seq","difficulty":3,"statement":"Последовательность: 111, 213, 141, 516, 171, 819, ?, 122. Найдите число вместо вопросительного знака.","answer":"201","solution":"Нечётные члены 111,141,171,… растут на 30 → 201.","image":null},{"id":"v7_21","school":"РФМШ","variant":"v7","num":21,"topic":"geo","difficulty":3,"statement":"Прямоугольник разделён на 9 меньших. Известны периметры: 10, C=8, 7, A=11, 9. Найдите периметр B.","answer":"7","solution":"Через ширины столбцов и высоты строк: B = 2(w2+h2) = 7.","image":"/figures/v7_q21.svg"},{"id":"v7_22","school":"РФМШ","variant":"v7","num":22,"topic":"sys","difficulty":2,"statement":"Найдите сумму натуральных решений системы: (2x−4)/5 + (2−x)/2 < 2; (2x+4)/3 − x/4 ≤ 3.","answer":"10","solution":"x≤4 (и x>−18). Натуральные 1,2,3,4. Сумма 10.","image":null},{"id":"v7_23","school":"РФМШ","variant":"v7","num":23,"topic":"geo","difficulty":2,"statement":"Фигура из квадрата (периметр 16 см) и трёх одинаковых треугольников (периметр каждого 9 см). Чему равен периметр фигуры?","answer":null,"solution":"Периметр зависит от того, как треугольники приставлены к квадрату — в приложении показан рисунок, сверьте по нему.","image":"/figures/v7_q23.png"},{"id":"v7_24","school":"РФМШ","variant":"v7","num":24,"topic":"ratio","difficulty":3,"statement":"Теплоход туда-обратно за 6,3 ч. Скорость в стоячей воде 18 км/ч, течение 2 км/ч. Расстояние между пристанями?","answer":"56","solution":"d/20 + d/16 = 6,3 → d=56 км.","image":null},{"id":"v7_25","school":"РФМШ","variant":"v7","num":25,"topic":"num","difficulty":2,"statement":"Белый шоколад по 14 в коробке, чёрный по 17. Всего 175 штук. Сколько всего распаковали коробок?","answer":"11","solution":"14·4 + 17·7 = 175 → коробок 4+7 = 11.","image":null},{"id":"v7_26","school":"РФМШ","variant":"v7","num":26,"topic":"num","difficulty":2,"statement":"Облачных дней на 14 больше, чем дождливых/снежных, и на 259 меньше солнечных. Сколько солнечных, если в году 365 дней?","answer":"299","solution":"3r+287=365 → r=26. Солнечных 26+273 = 299.","image":null},{"id":"v7_27","school":"РФМШ","variant":"v7","num":27,"topic":"num","difficulty":2,"statement":"A — первые 5 простых, B — первые 5 неотрицательных чётных, C — первые 5 нечётных натуральных. Найдите сумму элементов (B∪C)∩A.","answer":"17","solution":"(B∪C)={0..9}, ∩A={2,3,5,7}. Сумма 17.","image":null},{"id":"v7_28","school":"РФМШ","variant":"v7","num":28,"topic":"comb","difficulty":2,"statement":"Сколькими способами вписать 4,5,6,7,8 (каждое по разу), чтобы неравенства □>□>□<□<□ были верны?","answer":"6","solution":"Минимум 4 в центре. Выбрать 2 из {5,6,7,8} налево: C(4,2)=6.","image":"/figures/v7_q28.svg"},{"id":"v7_29","school":"РФМШ","variant":"v7","num":29,"topic":"pct","difficulty":3,"statement":"1-я неделя: цена 350000 тг. 2-я: покупателей +40%, выручка +24%. На сколько тг снизили цену?","answer":"40000","solution":"Цена2 = 350000·1,24/1,4 = 310000. Снижение 40000.","image":null},{"id":"v7_30","school":"РФМШ","variant":"v7","num":30,"topic":"sys","difficulty":3,"statement":"Найдите сумму всех целых x, НЕ являющихся решениями неравенства ||2x−20|−21| > 3.","answer":"80","solution":"|2x−20|∈[18,24] → x=19..22 и x=−2..1. Сумма 80.","image":null},{"id":"v9_1","school":"РФМШ","variant":"v9","num":1,"topic":"frac","difficulty":2,"statement":"Выполните действие: ((16 ч 32 мин) − (12 ч 50 мин)) : (37 мин).","answer":"6","solution":"3 ч 42 мин = 222 мин. 222/37 = 6.","image":null},{"id":"v9_2","school":"РФМШ","variant":"v9","num":2,"topic":"geo","difficulty":2,"statement":"Черепаха вышла из дома и вернулась. По графику движения определите расстояние (в метрах) от дома через 3 мин.","answer":null,"solution":"Значение считывается с графика — в приложении показан рисунок.","image":"/figures/v9_q2.png"},{"id":"v9_3","school":"РФМШ","variant":"v9","num":3,"topic":"pct","difficulty":1,"statement":"Сплав содержит 18% меди. Сколько кг сплава нужно, чтобы в нём было 54 кг меди?","answer":"300","solution":"54/0,18 = 300.","image":null},{"id":"v9_4","school":"РФМШ","variant":"v9","num":4,"topic":"ratio","difficulty":2,"statement":"Периметр треугольника 125 см, стороны 4:9:12. Найдите наибольшую сторону.","answer":"60","solution":"125/25=5, 12·5 = 60.","image":null},{"id":"v9_5","school":"РФМШ","variant":"v9","num":5,"topic":"num","difficulty":2,"statement":"Какую наибольшую цифру можно поставить вместо звёздочки, чтобы −6,5*7 > −6,586?","answer":"7","solution":"6,5d7 < 6,586 → d≤7. Наибольшая 7.","image":null},{"id":"v9_6","school":"РФМШ","variant":"v9","num":6,"topic":"seq","difficulty":2,"statement":"Ряд 0,2,6,12,20,30,42. Записали ещё два члена. Модуль их разности?","answer":"16","solution":"Дальше 56 и 72. |72−56| = 16.","image":null},{"id":"v9_7","school":"РФМШ","variant":"v9","num":7,"topic":"eq","difficulty":2,"statement":"Второе число на 3 больше первого. Частное первого на 4 равно частному второго на 5. Найдите первое число.","answer":"12","solution":"a/4=(a+3)/5 → a=12.","image":null},{"id":"v9_8","school":"РФМШ","variant":"v9","num":8,"topic":"frac","difficulty":3,"statement":"1-й день 30% поля, 2-й — 9/14 остатка, 3-й — остальные 15 га. Площадь поля?","answer":"60","solution":"0,25P = 15 → P=60 га.","image":null},{"id":"v9_9","school":"РФМШ","variant":"v9","num":9,"topic":"comb","difficulty":2,"statement":"Каждому по 7 конфет — останется 4; по 9 — не хватит 24. Сколько друзей?","answer":"14","solution":"2f=28 → f=14.","image":null},{"id":"v9_10","school":"РФМШ","variant":"v9","num":10,"topic":"eq","difficulty":2,"statement":"Арман нашёл на 18 больше половины грибов папы. Папа на 7 больше Армана. Сколько грибов вместе?","answer":"93","solution":"Арман 43, папа 50. Вместе 93.","image":null},{"id":"v9_11","school":"РФМШ","variant":"v9","num":11,"topic":"eq","difficulty":2,"statement":"Сумма трёх чисел на 16 больше первого, на 11 больше второго, на 9 больше третьего. Найдите произведение этих чисел.","answer":"126","solution":"Сумма 18. Числа 2,7,9. 2·7·9 = 126.","image":null},{"id":"v9_12","school":"РФМШ","variant":"v9","num":12,"topic":"eq","difficulty":2,"statement":"Операция a⊕b = 2a+3b. Найдите ((2m)⊕n) ⊕ (m⊕(2n)) при m=3, n=5.","answer":"162","solution":"27⊕36 = 54+108 = 162.","image":null},{"id":"v9_13","school":"РФМШ","variant":"v9","num":13,"topic":"geo","difficulty":2,"statement":"Какой угол (0..180) образуют стрелки в 10 часов 22 минуты?","answer":"179","solution":"|311 − 132| = 179°.","image":null},{"id":"v9_14","school":"РФМШ","variant":"v9","num":14,"topic":"geo","difficulty":3,"statement":"Квадрат со стороной 10 разрезали на 4 квадрата. Внутри отрезки AB, DC и дуги AD, BC (четверти радиуса 5). Найдите сумму площадей закрашенных частей.","answer":null,"solution":"Площадь считается по рисунку (дуги и отрезки) — в приложении показан чертёж.","image":"/figures/v9_q14.png"},{"id":"v9_15","school":"РФМШ","variant":"v9","num":15,"topic":"comb","difficulty":3,"statement":"Пять детей в шеренге, 37 флажков. Справа от Сабыржана 14, от Дамира 32, от Айгерим 20, от Куаныша 8. Сколько флажков у Меруерт?","answer":"8","solution":"Меруерт справа никого → у неё 8 флажков.","image":null},{"id":"v9_16","school":"РФМШ","variant":"v9","num":16,"topic":"ratio","difficulty":3,"statement":"13 тугриков = 26 динаров, 28 рупий = 21 динар, 14 рупий = 3 талера, 7 крон = 4 талера. Сколько тугриков за 21 крону?","answer":"21","solution":"21 крон → 12 талер → 56 рупий → 42 динара → 21 тугрик.","image":null},{"id":"v9_17","school":"РФМШ","variant":"v9","num":17,"topic":"seq","difficulty":3,"statement":"В числовом треугольнике каждое число — сумma трёх над ним. Найдите сумму чисел, замененных вопросительными знаками.","answer":"31","solution":"? = 6, 6 (4-я строка) и 19 (центр 5-й). Сумма 6+6+19 = 31.","image":"/figures/v9_q17.svg"},{"id":"v9_18","school":"РФМШ","variant":"v9","num":18,"topic":"spat","difficulty":2,"statement":"Куб объёмом 8 дм³ состоит из кубиков со стороной 1 см. Длина цепочки из всех кубиков в метрах?","answer":"80","solution":"8000 кубиков × 1 см = 8000 см = 80 м.","image":null},{"id":"v9_19","school":"РФМШ","variant":"v9","num":19,"topic":"sys","difficulty":2,"statement":"Найдите сумму всех целых решений: −5/6 < 5 1/2 − x < 2 1/6.","answer":"15","solution":"3,33<x<6,33 → x=4,5,6. Сумма 15.","image":null},{"id":"v9_20","school":"РФМШ","variant":"v9","num":20,"topic":"frac","difficulty":3,"statement":"Вычислите: (1+1/2)(1+1/3)(1+1/4)…(1+1/99).","answer":"50","solution":"Телескоп: 100/2 = 50.","image":null},{"id":"v9_21","school":"РФМШ","variant":"v9","num":21,"topic":"ratio","difficulty":3,"statement":"Из A в B (10 км) турист 7 1/2 км/ч. Одновременно из B в том же направлении второй, скорость в 2 1/4 раза меньше. Через сколько минут первый догонит второго?","answer":"144","solution":"Отн. скорость 12,5/3 км/ч. 10/(12,5/3) = 2,4 ч = 144 мин.","image":null},{"id":"v9_22","school":"РФМШ","variant":"v9","num":22,"topic":"num","difficulty":2,"statement":"17! = 35568*428096000. Какая цифра должна стоять вместо звёздочки?","answer":"7","solution":"17! = 355687428096000 → * = 7.","image":null},{"id":"v9_23","school":"РФМШ","variant":"v9","num":23,"topic":"sys","difficulty":3,"statement":"При каком натуральном n двойное неравенство 20 < |x−10| < n имеет ровно 13 натуральных решений?","answer":"34","solution":"x=31..43 (13 шт) → 43<10+n≤44 → n=34.","image":null},{"id":"v9_24","school":"РФМШ","variant":"v9","num":24,"topic":"num","difficulty":2,"statement":"Вычислите: 1+2−3+4+5−6+7+8−9+…+91+92−93.","answer":"1395","solution":"31 группа, группа k даёт 3k−3. Сумма 1395.","image":null},{"id":"v9_25","school":"РФМШ","variant":"v9","num":25,"topic":"geo","difficulty":2,"statement":"Вершины прямоугольника ABCD: A(−2;−3), B(−2;5), C(4;5). Найдите сумму координат точки пересечения диагоналей.","answer":"2","solution":"Центр = середина AC = (1;1). Сумма 2.","image":null},{"id":"v9_26","school":"РФМШ","variant":"v9","num":26,"topic":"num","difficulty":2,"statement":"Сколько натуральных пар (x,y): x+y<200 и 5x=7y?","answer":"16","solution":"x=7k, y=5k, 12k<200 → k=1..16 → 16 пар.","image":null},{"id":"v9_27","school":"РФМШ","variant":"v9","num":27,"topic":"comb","difficulty":3,"statement":"На плане дома соседние комнаты соединены дверью. Сколькими способами пройти из A в B, не проходя ни одну комнату дважды?","answer":null,"solution":"Число путей считается по плану — в приложении показан рисунок.","image":"/figures/v9_q27.png"},{"id":"v9_28","school":"РФМШ","variant":"v9","num":28,"topic":"pct","difficulty":3,"statement":"Среднее двух положительных чисел на 30% меньше большего. На сколько % это среднее больше меньшего?","answer":"75%","solution":"b=0,4a, среднее 0,7a. (0,7−0,4)/0,4 = 75%.","image":null},{"id":"v9_29","school":"РФМШ","variant":"v9","num":29,"topic":"eq","difficulty":3,"statement":"Найдите корень уравнения: x(x−3)/9 − 2(x²+9)/36 = (x−3)(x+6)/18.","answer":"1","solution":"После упрощения −18x = −18 → x=1.","image":null},{"id":"v9_30","school":"РФМШ","variant":"v9","num":30,"topic":"num","difficulty":3,"statement":"К 50-значному числу из одних 7 прибавили 50-значное из одних 9. Чему равна сумма цифр полученной суммы?","answer":"350","solution":"Сумма = 1, затем 49 семёрок, затем 6. 1+49·7+6 = 350.","image":null},{"id":"bil13_2","school":"БИЛ","variant":"bil13","num":2,"topic":"eq","difficulty":2,"statement":"Найдите значение выражения: 4(15x+8)+3(6x−5), при x=4.","answer":"329","solution":"4(60+8)+3(24−5)=272+57=329.","image":null},{"id":"bil13_3","school":"БИЛ","variant":"bil13","num":3,"topic":"eq","difficulty":2,"statement":"Упростите и найдите значение: (18·9+x)+(y+722:19), при x=36, y=14.","answer":"250","solution":"(162+36)+(14+38)=198+52=250.","image":null},{"id":"bil13_4","school":"БИЛ","variant":"bil13","num":4,"topic":"eq","difficulty":2,"statement":"Решите уравнение: 91+48:(11−b)=99.","answer":"5","solution":"48/(11−b)=8 → 11−b=6 → b=5.","image":null},{"id":"bil13_5","school":"БИЛ","variant":"bil13","num":5,"topic":"ratio","difficulty":2,"statement":"Кызылорда–Алматы 1170 км. Поезд из Кызылорды 70 км/ч ехал 6 ч, затем навстречу из Алматы вышел поезд 80 км/ч. Сколько часов едет поезд из Алматы до встречи?","answer":"5","solution":"Проехал 420 км, осталось 750. 750/(70+80)=5 ч.","image":null},{"id":"bil13_6","school":"БИЛ","variant":"bil13","num":6,"topic":"eq","difficulty":2,"statement":"Решите уравнение: 86−49:(2x−5)=79.","answer":"6","solution":"49/(2x−5)=7 → 2x−5=7 → x=6.","image":null},{"id":"bil13_7","school":"БИЛ","variant":"bil13","num":7,"topic":"eq","difficulty":2,"statement":"Упростите и найдите значение: 8(2x+y)+3(x−y), при x=2, y=9.","answer":"83","solution":"8·13+3·(−7)=104−21=83.","image":null},{"id":"bil13_8","school":"БИЛ","variant":"bil13","num":8,"topic":"eq","difficulty":2,"statement":"Упростите: (161x−92x):23+17x.","answer":"20x","solution":"69x/23+17x=3x+17x=20x.","image":null},{"id":"bil13_9","school":"БИЛ","variant":"bil13","num":9,"topic":"eq","difficulty":2,"statement":"Упростите и найдите значение: 5(6x+7y)+2(4x−15y), при x=3, y=6.","answer":"144","solution":"38x+5y=114+30=144.","image":null},{"id":"bil13_10","school":"БИЛ","variant":"bil13","num":10,"topic":"eq","difficulty":2,"statement":"Упростите: (581y·5):83−18y.","answer":"17y","solution":"2905y/83−18y=35y−18y=17y.","image":null},{"id":"bil13_13","school":"БИЛ","variant":"bil13","num":13,"topic":"num","difficulty":2,"statement":"Частное двух чисел равно НОД(28,20). Разность этих чисел равна НОК(7,9). Найдите эти числа.","answer":"84 и 21","solution":"НОД=4, НОК=63. a=4b, 3b=63 → b=21, a=84.","image":null},{"id":"bil13_14","school":"БИЛ","variant":"bil13","num":14,"topic":"eq","difficulty":2,"statement":"Упростите: 203·4x−750x+90:15+14.","answer":"62x+20","solution":"812x−750x+6+14=62x+20.","image":null},{"id":"bil13_15","school":"БИЛ","variant":"bil13","num":15,"topic":"eq","difficulty":2,"statement":"Упростите: 18·7x−270x:45+35x.","answer":"155x","solution":"126x−6x+35x=155x.","image":null},{"id":"bil13_16","school":"БИЛ","variant":"bil13","num":16,"topic":"eq","difficulty":2,"statement":"Выполните деление: (245a+147b−98c):49.","answer":"5a+3b−2c","solution":"245/49=5, 147/49=3, 98/49=2 → 5a+3b−2c.","image":null},{"id":"bil13_17","school":"БИЛ","variant":"bil13","num":17,"topic":"num","difficulty":2,"statement":"Частное двух чисел равно НОД(35,77). Сумма этих чисел равна НОД(160,96). Найдите эти числа.","answer":"4 и 28","solution":"НОД=7, НОД(160,96)=32. a=7b, 8b=32 → b=4, a=28.","image":null},{"id":"bil13_20","school":"БИЛ","variant":"bil13","num":20,"topic":"work","difficulty":2,"statement":"14 старшим и 8 начальным классам раздали x кусков мела. Каждому старшему классу выделяется y кусков. Сколько кусков каждому начальному классу? x=36, y=2.","answer":"1","solution":"Старшим 14·2=28, осталось 8 на 8 классов → по 1.","image":null},{"id":"bil13_27","school":"БИЛ","variant":"bil13","num":27,"topic":"eq","difficulty":2,"statement":"Решите уравнение: 71,93+y=98,15.","answer":"26,22","solution":"98,15−71,93=26,22.","image":null},{"id":"bil13_28","school":"БИЛ","variant":"bil13","num":28,"topic":"eq","difficulty":2,"statement":"Ученик задумал число, прибавил 14,8, уменьшил результат на 3,56 и получил 75,29. Какое число он задумал?","answer":"64,05","solution":"75,29−14,8+3,56=64,05.","image":null},{"id":"bil13_29","school":"БИЛ","variant":"bil13","num":29,"topic":"frac","difficulty":2,"statement":"Вычислите, используя распределительное свойство: 10,27·5,1+8,3·5,1.","answer":"94,707","solution":"5,1·(10,27+8,3)=5,1·18,57=94,707.","image":null},{"id":"bil13_31","school":"БИЛ","variant":"bil13","num":31,"topic":"pct","difficulty":2,"statement":"Расстояние авто проехал за 3 часа. За 1-й час — 37,5% всего пути, за 2-й час — 36% оставшегося. Сколько процентов всего пути проехал за 3-й час?","answer":"40%","solution":"Осталось 62,5%. 2-й час 36%·62,5%=22,5%. 3-й: 100−37,5−22,5=40%.","image":null},{"id":"bil13_32","school":"БИЛ","variant":"bil13","num":32,"topic":"eq","difficulty":2,"statement":"Упростите и найдите значение: 4(b+0,8)+1,7b, при b=2,3.","answer":"16,31","solution":"5,7b+3,2=13,11+3,2=16,31.","image":null},{"id":"bil13_33","school":"БИЛ","variant":"bil13","num":33,"topic":"pct","difficulty":2,"statement":"Сколько граммов воды добавить в 150 г раствора соды с концентрацией 40%, чтобы получить концентрацию 15%?","answer":"250","solution":"Соды 60 г. 60/(150+x)=0,15 → 150+x=400 → x=250.","image":null},{"id":"bil13_34","school":"БИЛ","variant":"bil13","num":34,"topic":"geo","difficulty":2,"statement":"Отношение ширины прямоугольника к длине 3:5. Длина на 6 см больше ширины. Найдите периметр.","answer":"48","solution":"2k=6 → k=3. Ширина 9, длина 15. P=2(9+15)=48.","image":null},{"id":"bil13_35","school":"БИЛ","variant":"bil13","num":35,"topic":"eq","difficulty":2,"statement":"Упростите и найдите значение: 6(a+1,5)−2,8a, при a=1,5.","answer":"13,8","solution":"3,2a+9=4,8+9=13,8.","image":null},{"id":"bil13_39","school":"БИЛ","variant":"bil13","num":39,"topic":"eq","difficulty":2,"statement":"Решите уравнение: (7−0,2x)·1,4=7,56.","answer":"8","solution":"7−0,2x=5,4 → 0,2x=1,6 → x=8.","image":null},{"id":"bil13_42","school":"БИЛ","variant":"bil13","num":42,"topic":"seq","difficulty":2,"statement":"Найдите следующее число: 5, 8, 6, 12, 8, 17, 11, 23, 15, 30, ?","answer":"20","solution":"Нечётные члены 5,6,8,11,15,? растут на 1,2,3,4,5 → 20.","image":null},{"id":"bil13_1","school":"БИЛ","variant":"bil13","num":1,"topic":"ratio","difficulty":2,"statement":"Теплоход с собственной скоростью 19 км/ч проплыл 2 часа по течению и 3 часа против течения. Скорость реки 2 км/ч. Какую часть всего пути теплоход плыл против течения?","answer":"17/31","solution":"По течению 21·2=42 км, против 17·3=51 км. Всего 93. Против: 51/93=17/31.","image":null},{"id":"bil13_24","school":"БИЛ","variant":"bil13","num":24,"topic":"eq","difficulty":2,"statement":"Упростите: (128a+35b)·9−1100a−315b.","answer":"52a","solution":"1152a+315b−1100a−315b=52a.","image":null},{"id":"bil13_49","school":"БИЛ","variant":"bil13","num":49,"topic":"comb","difficulty":2,"statement":"Дана операция: 1∘2=4, 2∘3=18, 3∘4=48. Чему равно 3∘5?","answer":"75","solution":"a∘b = a·b². 3·5²=3·25=75.","image":null}];

export const variants = [{"id":"rfmsh2025_v1","title":"РФМШ 2025 · Вариант 1 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"spat","statement":"Какая грань будет сверху, если кубик из данной развёртки поставить на закрашенную грань?","answer":"4","image":"/figures/v1_q1.png","solution":"Полоса 2–серая–3–4 сворачивается в 4 боковые грани, где серая грань оказывается напротив грани 4. Если поставить кубик на серую грань, сверху окажется 4.","note":null},{"num":2,"topic":"eq","statement":"Бахыт старше сына в 5 раз, сумма их возрастов 360 месяцев (30 лет). Через сколько лет Бахыт будет старше сына в 3 раза?","answer":"5","image":null,"solution":"Сын 5, Бахыт 25. 25+t=3(5+t) → 10=2t → t=5 лет.","note":null},{"num":3,"topic":"work","statement":"У Асана 12 годовых оценок, средний балл 3,75. По скольким предметам поднять оценку на 1 балл, чтобы средний стал 4?","answer":"3","image":null,"solution":"Сумма=45. Для среднего 4 нужна сумма 48. Разница 3 → поднять 3 предмета.","note":null},{"num":4,"topic":"pct","statement":"Спортсекции посещают 360 студентов = 40% от всех. 10% всех ходят на английский. 30% из тех, кто на английском, занимаются танцами. Сколько танцуют?","answer":"27","image":null,"solution":"Всего 900. Английский 90. Танцы 30% от 90 = 27.","note":null},{"num":5,"topic":"pct","statement":"Число жирафов равно 80% от числа обезьян. Сколько процентов от жирафов составляют обезьяны?","answer":"125%","image":null,"solution":"G=0,8·M → M/G = 1,25 = 125%.","note":null},{"num":6,"topic":"eq","statement":"Найдите a, при котором значения выражений (2(a+b+x)−3a−3(−a−2b)−8b)/2 и x+2 равны.","answer":"2","image":null,"solution":"Числитель = 2a+2x, делённое на 2 даёт a+x. a+x = x+2 → a=2.","note":null},{"num":7,"topic":"num","statement":"Если сегодня вторник, какой день недели будет через 340 дней? (Ответ — номер дня от 1 до 7, понедельник = 1.)","answer":"6","image":null,"solution":"340 mod 7 = 4. Вторник + 4 = суббота = 6.","note":null},{"num":8,"topic":"comb","statement":"Семь человек за круглым столом, каждый говорит: оба моих соседа лжецы. Лжецы всегда лгут, остальные всегда правдивы. Сколько лжецов?","answer":"4","image":null,"solution":"Правдивый окружён лжецами, у каждого лжеца есть хотя бы один правдивый сосед. На 7 местах это даёт 4 лжеца.","note":null},{"num":9,"topic":"num","statement":"Шестизначное число 1234ab кратно 9 и состоит из разных цифр. Какое наибольшее значение принимает a·b?","answer":"72","image":null,"solution":"Сумма цифр 10+a+b кратна 9 → a+b=17 (из свободных 0,5,6,7,8,9). 8·9 = 72.","note":null},{"num":10,"topic":"geo","statement":"Вычислите x, если точки A, O, D лежат на одной прямой (углы 50°, 3x°, 2x°).","answer":"26","image":"/figures/v1_q10.png","solution":"50 + 3x + 2x = 180 → 5x = 130 → x = 26.","note":null},{"num":11,"topic":"eq","statement":"Найдите целый корень уравнения: (5,5 + |6x+4|:2)/3 = 4,5.","answer":"2","image":null,"solution":"5,5 + |6x+4|/2 = 13,5 → |6x+4| = 16 → x=2 (целый).","note":null},{"num":12,"topic":"sys","statement":"Найдите сумму всех целых решений неравенства: 9 < 2x+3 ≤ 13.","answer":"9","image":null,"solution":"3 < x ≤ 5 → x=4,5. Сумма = 9.","note":null},{"num":13,"topic":"pct","statement":"На первой остановке израсходовано 20% бензина, на второй 25% остатка. Оставшегося на 10 л больше израсходованного. Сколько литров было изначально?","answer":"50","image":null,"solution":"Израсходовано 0,4V, осталось 0,6V. 0,6V−0,4V=0,2V=10 → V=50.","note":null},{"num":14,"topic":"geo","statement":"Точки P(−5;0) и F(−1;4), F — середина отрезка PB. Найдите сумму координат точки B.","answer":"11","image":null,"solution":"B = 2F − P = (3;8). Сумма = 11.","note":null},{"num":15,"topic":"geo","statement":"Площадь первого колеса 1600π, второго 400π. Радиус третьего = 50% суммы радиусов первых двух. Найдите площадь третьего (π=3,14).","answer":"2826","image":null,"solution":"r1=40, r2=20, r3=30. S = π·900 = 2826.","note":null},{"num":16,"topic":"work","statement":"20 человек несут 200 кг: мужчина 20 кг, женщина 5 кг, ребёнок 3 кг. Найдите произведение чисел мужчин, женщин и детей.","answer":"160","image":null,"solution":"m=8, w=2, c=10. Произведение = 160.","note":null},{"num":17,"topic":"pct","statement":"Все цены снизили на 15%. Скидочная цена шоколада 2210 тг. На сколько тг подешевел шоколад?","answer":"390","image":null,"solution":"Исходная 2210/0,85 = 2600. Скидка = 390.","note":null},{"num":18,"topic":"geo","statement":"Измерения прямоугольного параллелепипеда — простые числа, объём 42. Найдите площадь поверхности.","answer":"82","image":null,"solution":"42=2·3·7. S = 2(6+21+14) = 82.","note":null},{"num":19,"topic":"ratio","statement":"Поезд проходит мост 500 м за 1 минуту, мимо столба — за 20 секунд. Какова длина поезда?","answer":"250","image":null,"solution":"L=20v, L+500=60v → v=12,5 м/с, L=250 м.","note":null},{"num":20,"topic":"ratio","statement":"Реки: 4248, 2450, 2488, 2214 км. Найдите их общую длину в см на карте масштаба 1:2 500 000.","answer":"456","image":null,"solution":"Сумма 11400 км = 1,14·10^9 см. /2 500 000 = 456 см.","note":null},{"num":21,"topic":"num","statement":"Сумма двух чисел 2010. Частное от деления большего на меньшее равно 11. Чему равен остаток?","answer":"6","image":null,"solution":"12b+r=2010, b=167, r=6. (Условие допускает неоднозначность — стандартный ответ 6.)","note":null},{"num":22,"topic":"spat","statement":"Сколько всего квадратов, ограниченных линиями сетки, можно найти на рисунке?","answer":"20","image":"/figures/v1_q22.png","solution":"Сетка 3×4: 1×1 = 12, 2×2 = 6, 3×3 = 2. Всего 20.","note":null},{"num":23,"topic":"eq","statement":"Решите уравнение: (2,3x−11,2)/0,7 = (1,7x−9,4)/(−2,1).","answer":"5","image":null,"solution":"Крест-накрест: −4,83x+23,52 = 1,19x−6,58 → 30,1 = 6,02x → x=5.","note":null},{"num":24,"topic":"comb","statement":"Операция a⊕b = (2a−1)(2b−1). Вычислите 2⊕(3⊕4).","answer":"207","image":null,"solution":"3⊕4 = 5·7 = 35. 2⊕35 = 3·69 = 207.","note":null},{"num":25,"topic":"pct","statement":"Мандариновое дерево даёт 300 кг, апельсиновое 800 кг, в среднем 600 кг с дерева. Каков процент мандариновых деревьев?","answer":"40%","image":null,"solution":"o=1,5m → m/(2,5m) = 0,4 = 40%.","note":null},{"num":26,"topic":"sys","statement":"Сколько целых решений имеет двойное неравенство 11 < |2−x| ≤ 14?","answer":"6","image":null,"solution":"x−2 ∈ {12,13,14} или {−12,−13,−14} → 6 решений.","note":null},{"num":27,"topic":"eq","statement":"Четыре числа: +2 к первому, −2 от второго, ×2 третье, ÷2 четвёртое — станут равными. Сумма всех четырёх 45. Найдите первое число.","answer":"8","image":null,"solution":"Общее k=10. Первое = k−2 = 8.","note":null},{"num":28,"topic":"num","statement":"Вычислите: 21 + 28 + 35 + … + 588 + 595 + 602.","answer":"26166","image":null,"solution":"n=84, сумма = 84·(21+602)/2 = 26166.","note":null},{"num":29,"topic":"num","statement":"Найдите наименьшее натуральное n такое, что n! делится на 2023.","answer":"34","image":null,"solution":"2023 = 7·17². Нужны два множителя 17: 17 и 34 → n=34.","note":null},{"num":30,"topic":"pct","statement":"Два шоколада с 20 г молока и 40 г воды → 180 г горячего шоколада, 42% какао. Какао в первом 70%, во втором 30%. Сколько граммов первого шоколада?","answer":"99","image":null,"solution":"c1+c2=120. 0,7c1+0,3c2 = 75,6 → c1 = 99 г.","note":null}]},{"id":"rfmsh2025_v2","title":"РФМШ 2025 · Вариант 2 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"eq","statement":"Найдите корень уравнения: (x+3)/65 = 4/13.","answer":"17","image":null,"solution":"x+3 = 65·4/13 = 20 → x=17.","note":null},{"num":2,"topic":"num","statement":"Найдите делимое, если делитель 13, неполное частное 12, остаток 10.","answer":"166","image":null,"solution":"13·12+10 = 166.","note":null},{"num":3,"topic":"work","statement":"Первая труба наполняет бассейн за 6 ч, вторая за 12 ч. За сколько часов наполнят вместе?","answer":"4","image":null,"solution":"1/6+1/12 = 1/4 → 4 ч.","note":null},{"num":4,"topic":"work","statement":"На дворе куры и овцы: 35 голов и 94 ноги. Сколько кур?","answer":"23","image":null,"solution":"c+s=35, 2c+4s=94 → s=12, c=23.","note":null},{"num":5,"topic":"num","statement":"Сумма шести последовательных чисел равна 441. Найдите произведение наибольшего и наименьшего.","answer":"5396","image":null,"solution":"6n+15=441 → n=71. Числа 71..76. 71·76 = 5396.","note":null},{"num":6,"topic":"ratio","statement":"Первая труба на чертеже 24 см, реально 6 м. Сколько см на чертеже у трубы длиной 4,5 м?","answer":"18","image":null,"solution":"Масштаб 24см/6м = 4 см/м. 4,5·4 = 18 см.","note":null},{"num":7,"topic":"geo","statement":"Длина первой окружности 13, её диаметр равен радиусу второй. Чему равна длина второй окружности?","answer":"26","image":null,"solution":"C2 = 2π·(d1) = 2·(π·d1) = 2·13 = 26.","note":null},{"num":8,"topic":"frac","statement":"Упростите и найдите при m=1944: 9/10·m − 2/15·m − 3/5·m.","answer":"324","image":null,"solution":"Коэффициент 1/6. 1944/6 = 324.","note":null},{"num":9,"topic":"geo","statement":"Прямые AB, CD, EF пересекаются в O, AB⊥CD, ∠AOE=35°. Найдите ∠COF.","answer":"55","image":"/figures/v2_q9.svg","solution":"∠EOC = 90−35 = 55°. ∠COF вертикален ∠DOE = 55°.","note":null},{"num":10,"topic":"ratio","statement":"На прямой 100 точек, расстояние между соседними 7. Расстояние между крайними?","answer":"693","image":null,"solution":"99·7 = 693.","note":null},{"num":11,"topic":"comb","statement":"Заяц и черепаха бегут 100 м. Когда заяц финишировал, черепахе осталось 90 м. На сколько метров отодвинуть старт зайца для ничьей?","answer":"900","image":null,"solution":"Скорости 10:1. (100+x)/10=100 → x=900.","note":null},{"num":12,"topic":"num","statement":"Сколько натуральных чисел от 1 до 100 делятся на 2, но не на 3?","answer":"34","image":null,"solution":"50 − 16 = 34.","note":null},{"num":13,"topic":"pct","statement":"Депозит 10% годовых. Через 2 года на счёте 60500 тг. Сколько вложили изначально?","answer":"50000","image":null,"solution":"P·1,21 = 60500 → P=50000.","note":null},{"num":14,"topic":"sys","statement":"Найдите наибольшее целое решение: (1−2x)/7 − 3 < −x − (2x+3)/5.","answer":"2","image":null,"solution":"39x<79 → x<2,03 → x=2.","note":null},{"num":15,"topic":"num","statement":"Найдите НОД(a,b): a=2·3·25·49·11, b=2·9·5·7·11·13.","answer":"2310","image":null,"solution":"НОД = 2·3·5·7·11 = 2310.","note":null},{"num":16,"topic":"frac","statement":"Вычислите: 26·(3 − 1/4 + 2/3)·(6/13 − 7/26 + 2/52) + ((−1/8 + 1 − 3/4)·52).","answer":"27","image":null,"solution":"Первая часть 20,5, вторая 6,5. Сумма 27.","note":null},{"num":17,"topic":"comb","statement":"К площади 6 улиц: 4 двусторонние, 2 односторонние (к площади). Приехать и покинуть площадь. Сколькими способами?","answer":"20","image":null,"solution":"Въезд 6 способов, выезд по 4 двусторонним (разной улицей): 2·4+4·3 = 20.","note":null},{"num":18,"topic":"frac","statement":"Вычислите: −|7,14| : |−2,1| − (2,15 − |−4,3|) + (1,5 + |−4,75|).","answer":"5","image":null,"solution":"−3,4 + 2,15 + 6,25 = 5.","note":null},{"num":19,"topic":"spat","statement":"Сколько всего треугольников можно найти на рисунке?","answer":null,"image":"/figures/v2_q19.png","solution":"Подсчёт зависит от рисунка. В приложении показан чертёж — сверьте по нему.","note":null},{"num":20,"topic":"ratio","statement":"Две дороги: первая на 10 км длиннее. Первый авто 3,5 ч по первой, второй 2,5 ч по второй. Скорость первого на 20 км/ч меньше. Найдите скорость первого.","answer":"60","image":null,"solution":"3,5v = 2,5(v+20)+10 → v=60 км/ч.","note":null},{"num":21,"topic":"pct","statement":"28 альбомов за 50400 тг, наценка 20%, продал 15. Остальные с доп. наценкой 10%. Найдите прибыль.","answer":"12420","image":null,"solution":"Себестоимость 1800. Выручка 32400+30420=62820. Прибыль 62820−50400=12420.","note":null},{"num":22,"topic":"eq","statement":"Найдите (a+c)(b+d)/(cd), если a:b=c:d=3 и b:d=−7.","answer":"36","image":null,"solution":"a=−21d, c=3d, b=−7d. (−18d)(−6d)/(3d²)=36.","note":null},{"num":23,"topic":"num","statement":"Разность суммы первых 50 натуральных чисел и суммы первых 25 нечётных чисел.","answer":"650","image":null,"solution":"1275 − 625 = 650.","note":null},{"num":24,"topic":"geo","statement":"A(−3), B(15), C между ними, AC=8·BC. Найдите координату C.","answer":"13","image":null,"solution":"9BC=18 → BC=2, AC=16. C=−3+16=13.","note":null},{"num":25,"topic":"num","statement":"Сумма всех натуральных n, при которых 24/(n+4) — целое число.","answer":"34","image":null,"solution":"n+4 ∈ {6,8,12,24} → n=2,4,8,20. Сумма 34.","note":null},{"num":26,"topic":"geo","statement":"В окружность радиусом 20 вписан квадрат. Найдите сумму площадей закрашенных частей (π=3,14).","answer":"456","image":"/figures/v2_q26.svg","solution":"Круг 1256, квадрат 800. 1256−800 = 456.","note":null},{"num":27,"topic":"sys","statement":"Найдите сумму всех целых решений: 2 < |x/2 − 3| ≤ 5.","answer":"72","image":null,"solution":"x=11..16 (сумма 81) и x=−4..1 (сумма −9). Итого 72.","note":null},{"num":28,"topic":"ratio","statement":"Шёл время t со скоростью 4 км/ч, потом 2t со скоростью 7 км/ч. Средняя скорость?","answer":"6","image":null,"solution":"(4t+14t)/(3t) = 18/3 = 6 км/ч.","note":null},{"num":29,"topic":"num","statement":"Наименьшее натуральное n такое, что n² делится на 2024.","answer":"1012","image":null,"solution":"2024=2³·11·23. n=2²·11·23 = 1012.","note":null},{"num":30,"topic":"ratio","statement":"B на 160 км ниже A по реке (течение 4 км/ч). Из B плот и моторная лодка (20 км/ч) к A; достигнув A, лодка поворачивает. Через сколько часов догонит плот?","answer":"20","image":null,"solution":"До A: 160/16=10 ч. Далее 24(t−10)=160+4t → t=20 ч.","note":null}]},{"id":"rfmsh2025_v3","title":"РФМШ 2025 · Вариант 3 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"ratio","statement":"Отношение двух чисел 3:4, сумма 21. Найдите большее.","answer":"12","image":null,"solution":"21/7=3, большее 4·3=12.","note":null},{"num":2,"topic":"frac","statement":"Вычислите: (3 1/5 + 2 1/4) : 1/5 − 24 3/4 + 10,5.","answer":"13","image":null,"solution":"(16/5+9/4)·5 = 27,25. 27,25−24,75+10,5 = 13.","note":null},{"num":3,"topic":"num","statement":"Найдите НОК чисел 225 и 180.","answer":"900","image":null,"solution":"2²·3²·5² = 900.","note":null},{"num":4,"topic":"frac","statement":"Вычислите: (|3−4| − |6−8|·|3−5|)·(1 − |2−5|).","answer":"6","image":null,"solution":"(1−4)·(1−3) = (−3)(−2) = 6.","note":null},{"num":5,"topic":"seq","statement":"Ряд 1,2,2,3,3,3,4,4,4,4,… (число k повторяется k раз). На каком месте последний раз встречается 10?","answer":"55","image":null,"solution":"1+2+…+10 = 55.","note":null},{"num":6,"topic":"num","statement":"При делении числа на 17 и 15 частные одинаковы; на 15 остаток 8, на 17 делится без остатка. Найдите число.","answer":"68","image":null,"solution":"17q = 15q+8 → q=4, число 68.","note":null},{"num":7,"topic":"geo","statement":"Две прямые пересекаются, сумма трёх из четырёх углов 227°. Чему равен четвёртый?","answer":"133","image":null,"solution":"360−227 = 133°.","note":null},{"num":8,"topic":"frac","statement":"Скольким минутам равна 5/144 часть суток?","answer":"50","image":null,"solution":"1440·5/144 = 50 мин.","note":null},{"num":9,"topic":"geo","statement":"Вычислите x, если точки A, O, D на одной прямой (углы 4x°+30° и 2x°).","answer":"25","image":"/figures/v3_q9.svg","solution":"4x+30+2x=180 → 6x=150 → x=25.","note":null},{"num":10,"topic":"eq","statement":"При каком a число x=−3 является корнем уравнения (2a−1)(|x|−2)=5?","answer":"3","image":null,"solution":"(2a−1)·1=5 → a=3.","note":null},{"num":11,"topic":"geo","statement":"Периметр прямоугольника, если его площадь 140 см², а длина 70 см?","answer":"144","image":null,"solution":"Ширина 2. P=2(70+2)=144.","note":null},{"num":12,"topic":"eq","statement":"Найдите корень уравнения: 2 − 5/(2 − 3/(4−x)) = 7.","answer":"3","image":null,"solution":"2−3/(4−x)=−1 → 4−x=1 → x=3.","note":null},{"num":13,"topic":"geo","statement":"Точки A,B,C,D последовательно, A=15, B=23, |AB|=2|BC|, |BC|=2|CD|. Найдите координату D.","answer":"29","image":"/figures/v3_q13.svg","solution":"BC=4, CD=2. C=27, D=29.","note":null},{"num":14,"topic":"sys","statement":"Всего 64 студента, 4 не в организациях. Части диаграммы: x+6, 2x, 3x−12. Сколько в обеих организациях?","answer":"22","image":"/figures/v3_q14.svg","solution":"6x−2=64 → x=11. Обе = 2x = 22.","note":null},{"num":15,"topic":"pct","statement":"Цену повысили на 10%, затем на 20%. На сколько процентов выросла первоначальная цена?","answer":"32%","image":null,"solution":"1,1·1,2 = 1,32 → 32%.","note":null},{"num":16,"topic":"num","statement":"Двузначное число на 45 меньше числа с теми же цифрами наоборот, сумма цифр 11. Найдите произведение цифр.","answer":"24","image":null,"solution":"b−a=5, a+b=11 → 38. 3·8=24.","note":null},{"num":17,"topic":"num","statement":"В таблице 10×10 закрашены все клетки пяти строк и трёх столбцов. Сколько клеток остались незакрашенными?","answer":"35","image":null,"solution":"Закрашено 50+30−15=65. Осталось 35.","note":null},{"num":18,"topic":"work","statement":"Полный бидон молока 30 кг, наполовину 18 кг. Сколько весит бидон, заполненный на четверть?","answer":"12","image":null,"solution":"Молоко 24, бидон 6. 6+6 = 12 кг.","note":null},{"num":19,"topic":"ratio","statement":"Собака 2700 м за 5 мин, заяц 1060 м за 2 мин, заяц в 300 м впереди. За сколько минут собака догонит?","answer":"30","image":null,"solution":"540−530 = 10 м/мин. 300/10 = 30 мин.","note":null},{"num":20,"topic":"frac","statement":"1-й месяц 3/11 плана, 2-й 1/4 остатка, 3-й остальное. 1-й на 10 машин больше 2-го. Сколько за 3-й месяц?","answer":"60","image":null,"solution":"План 110. 3-й = 6/11·110 = 60.","note":null},{"num":21,"topic":"sys","statement":"Наименьшее целое решение: 0,8(2x−3) − 0,2(2x−5) > 14,5.","answer":"14","image":null,"solution":"1,2x > 15,9 → x>13,25 → 14.","note":null},{"num":22,"topic":"num","statement":"Процент сдавших экзамен в интервале 96,8%–97,6%. Наименьшее возможное число учеников?","answer":"32","image":null,"solution":"(n−1)/n ≥ 0,968 → n≥32. 31/32 = 96,875%.","note":null},{"num":23,"topic":"comb","statement":"Сколько пятизначных чисел, делящихся на 3, можно составить из цифр 1,2,3,4,5 ровно по разу?","answer":"120","image":null,"solution":"Сумма цифр 15 делится на 3 → все 5! = 120.","note":null},{"num":24,"topic":"num","statement":"На доске 1..8. Стирают a,b и пишут ab/2. Осталось одно число. Чему оно равно?","answer":"315","image":null,"solution":"Каждая операция делит произведение на 2. 8!/2^7 = 40320/128 = 315.","note":null},{"num":25,"topic":"work","statement":"Двое вместе за 30 дней. После 6 дней вместе первый один заканчивает за 40 дней. За сколько дней второй один?","answer":"75","image":null,"solution":"Первый 1/50, второй 1/30−1/50 = 1/75 → 75 дней.","note":null},{"num":26,"topic":"num","statement":"Десять последовательных целых. На сколько сумма пяти наибольших больше суммы пяти наименьших?","answer":"25","image":null,"solution":"Каждая пара отличается на 5. 5·5 = 25.","note":null},{"num":27,"topic":"work","statement":"Бассейн из двух труб за 7,5 ч. Отношение времени первой к второй 3:5. За сколько наполнит только вторая?","answer":"20","image":null,"solution":"t1=3k, t2=5k. 8/(15k)=1/7,5 → k=4, t2=20 ч.","note":null},{"num":28,"topic":"ratio","statement":"Пройдя половину, бегун увеличил скорость на 25% и прибыл на 0,5 ч раньше. Сколько минут на весь маршрут?","answer":"270","image":null,"solution":"d/v=2,5 ч. Факт 1,8·2,5 = 4,5 ч = 270 мин.","note":null},{"num":29,"topic":"comb","statement":"Три бегуна 100 м. Арман финишировал — Бауыржан отставал 10 м. Бауыржан финишировал — Саят отставал 10 м. На сколько отставал Саят от Армана?","answer":"19","image":null,"solution":"Саят = 90·0,9 = 81. Отставание 100−81 = 19 м.","note":null},{"num":30,"topic":"sys","statement":"Сколько целых решений имеет неравенство ||2x−3|−4| ≤ 5?","answer":"10","image":null,"solution":"|2x−3|≤9 → −3≤x≤6 → 10 целых.","note":null}]},{"id":"rfmsh2025_v4","title":"РФМШ 2025 · Вариант 4 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"eq","statement":"Найдите корень уравнения: 3(5−x)+13 = 4(3x−8).","answer":"4","image":null,"solution":"28−3x = 12x−32 → 15x=60 → x=4.","note":null},{"num":2,"topic":"geo","statement":"Длину прямоугольника увеличили в 2 раза, ширину в 3 раза. Во сколько раз увеличилась площадь?","answer":"6","image":null,"solution":"2·3 = 6.","note":null},{"num":3,"topic":"work","statement":"Сумма нескольких целых положительных чисел равна 72, их среднее 12. Сколько было чисел?","answer":"6","image":null,"solution":"72/12 = 6.","note":null},{"num":4,"topic":"sys","statement":"25 туристов: 12 хотят Байтерек, 19 — Астана Опера, все хотят хотя бы один объект. Сколько хотят и то, и другое?","answer":"6","image":null,"solution":"12+19−25 = 6.","note":null},{"num":5,"topic":"geo","statement":"На сколько градусов поворачивается часовая стрелка за 2,5 часа?","answer":"75","image":null,"solution":"30·2,5 = 75°.","note":null},{"num":6,"topic":"pct","statement":"Сколько получится, если к 35% числа 300 прибавить 15% числа 200?","answer":"135","image":null,"solution":"105+30 = 135.","note":null},{"num":7,"topic":"work","statement":"У кур и кроликов 15 голов и 44 ноги. Сколько кроликов?","answer":"7","image":null,"solution":"2r=14 → r=7.","note":null},{"num":8,"topic":"frac","statement":"Найдите число, обратное произведению чисел 6 1/4 и 1/25.","answer":"4","image":null,"solution":"25/4·1/25 = 1/4. Обратное = 4.","note":null},{"num":9,"topic":"num","statement":"В семье 4 несовершеннолетних. Трое на 2, 6, 8 лет старше младшего, возраст каждого — простое число. Сколько лет старшему?","answer":"13","image":null,"solution":"p=5: 5,7,11,13 — все простые. Старший 13.","note":null},{"num":10,"topic":"frac","statement":"Снегурочка съела 3/5 мандарина, осталось 1 1/3 кг. Сколько кг съела?","answer":"2","image":null,"solution":"Остаток 2/5 = 4/3 → всего 10/3. Съела 3/5·10/3 = 2 кг.","note":null},{"num":11,"topic":"frac","statement":"Вычислите: (1 + 1/(2+1:(3−1:4)))·26.","answer":"37","image":null,"solution":"Внутри 37/26. ·26 = 37.","note":null},{"num":12,"topic":"work","statement":"Две кошки за две минуты поймали двух мышей. За сколько минут три кошки поймают трёх мышей?","answer":"2","image":null,"solution":"1 кошка ловит 1 мышь за 2 мин → 3 кошки 3 мыши за 2 мин.","note":null},{"num":13,"topic":"pct","statement":"Когда бочка пуста на 40%, в ней на 30 л больше воды, чем когда полна на 20%. Сколько литров в полной бочке?","answer":"75","image":null,"solution":"60%V − 20%V = 40%V = 30 → V=75.","note":null},{"num":14,"topic":"eq","statement":"Найдите корень уравнения: 30/(1 + 10/(3 − 7/(4 + x/2))) − 4,5 = 0,5.","answer":"6","image":null,"solution":"Раскручиваем: 4+x/2 = 7 → x=6.","note":null},{"num":15,"topic":"geo","statement":"Периметр четырёхугольника 420 см. Первая сторона равна среднему арифметическому остальных трёх. Найдите первую сторону.","answer":"105","image":null,"solution":"a=S/3, a+S=420 → 4a=420 → a=105.","note":null},{"num":16,"topic":"ratio","statement":"Четыре числа по возрастанию, отношение последних трёх 2:5:6. Наибольшее больше первого на 17, сумма всех 40. Найдите второе число.","answer":"6","image":null,"solution":"k=3: числа 1,6,15,18. Второе = 6.","note":null},{"num":17,"topic":"pct","statement":"Цену телефона понизили на 30%, затем повысили на 20% — стал 16800 тг. Сколько стоил изначально?","answer":"20000","image":null,"solution":"0,84·P = 16800 → P=20000.","note":null},{"num":18,"topic":"ratio","statement":"В сникерсе орех:сахар = 5:2, сахар:шоколад = 3:11. Шоколада на 32 г больше сахара. Сколько весит сникерс?","answer":"86","image":null,"solution":"Орех:сахар:шоколад = 15:6:22. 16 частей = 32 г → 1 часть 2 г. 43·2 = 86 г.","note":null},{"num":19,"topic":"pct","statement":"Стороны прямоугольника 2:3. Короткую увеличили на 20%, длинную на 25%. На сколько % вырос периметр?","answer":"23%","image":null,"solution":"Стороны 2,4 и 3,75. P: 10 → 12,3 → +23%.","note":null},{"num":20,"topic":"spat","statement":"Найдите площадь фигуры на клетчатой бумаге с размером клетки 1×1.","answer":null,"image":"/figures/v4_q20.png","solution":"Площадь считается по фигуре (можно формулой Пика). В приложении показан рисунок — сверьте по нему.","note":null},{"num":21,"topic":"eq","statement":"Найдите корень уравнения: 6 : ((8 + 3x/5)/x + 9) = 3/5.","answer":"20","image":null,"solution":"(8+3x/5)/x = 1 → 8 = 2x/5 → x=20.","note":null},{"num":22,"topic":"geo","statement":"Найдите произведение всех x, при которых расстояние между A(3x+5) и B(2x) равно 3.","answer":"16","image":null,"solution":"|x+5|=3 → x=−2 или −8. Произведение 16.","note":null},{"num":23,"topic":"ratio","statement":"За 4 ч по течению катер проходит в 2,4 раза больше, чем за 2 ч против. Скорость течения 1,5 км/ч. Сколько км за 10 ч в стоячей воде?","answer":"165","image":null,"solution":"4(v+1,5)=4,8(v−1,5) → v=16,5. 16,5·10 = 165 км.","note":null},{"num":24,"topic":"geo","statement":"Сторона квадрата 80. Закрашенная фигура ограничена двумя четвертями дуг радиусом = стороне. Найдите её площадь (π=3,14).","answer":"3648","image":"/figures/v4_q24.svg","solution":"(π/2 − 1)·80² = 0,57·6400 = 3648.","note":null},{"num":25,"topic":"num","statement":"Вычислите: 11,2 + 12,2 + 13,2 + … + 99,2 + 100,2.","answer":"5013","image":null,"solution":"90 членов. 90·(11,2+100,2)/2 = 5013.","note":null},{"num":26,"topic":"comb","statement":"Из цифр 3,7,4,1,8 составили пятизначные числа без повторений. Сколько среди них чётных?","answer":"48","image":null,"solution":"Последняя цифра 4 или 8 (2), остальные 4! = 24. 2·24 = 48.","note":null},{"num":27,"topic":"geo","statement":"Часы показывают 10 часов 34 минуты. Найдите угол между стрелками (меньший 180°).","answer":"113","image":null,"solution":"|317 − 204| = 113°.","note":null},{"num":28,"topic":"eq","statement":"Найдите сумму корней уравнения: |x−6|/10 : 6/7 = 1 1/6 : 3 1/3.","answer":"12","image":null,"solution":"|x−6|=3 → x=9 или 3. Сумма 12.","note":null},{"num":29,"topic":"sys","statement":"Найдите наибольшее целое решение: 3x/4 − 5/6 < (3x+5)/6 − x/3.","answer":"2","image":null,"solution":"7x<20 → x<2,86 → x=2.","note":null},{"num":30,"topic":"geo","statement":"Точки A(x;2) и B(7;y) симметричны относительно C(4;3). Найдите x+y.","answer":"5","image":null,"solution":"x=1, y=4 → x+y=5.","note":null}]},{"id":"rfmsh2025_v5","title":"РФМШ 2025 · Вариант 5 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"comb","statement":"Арман, Болат, Азамат, Саян заняли первые 4 места. Трое ответили: 1) Арман ни первый, ни четвёртый; 2) Болат третий; 3) Азамат не был первым. Какое место занял Саян?","answer":"1","image":null,"solution":"Болат 3-й, Арман 2-й, Азамат не 1-й → 4-й, Саян 1-й.","note":null},{"num":2,"topic":"frac","statement":"Вычислите (7x+14y+21z)/(4z+2y−x), если x:y:z = 3:1:2.","answer":"11","image":null,"solution":"x=3,y=1,z=2: 77/7 = 11.","note":null},{"num":3,"topic":"frac","statement":"Вычислите: (12 ч 5 мин 21 сек − 11 ч 32 мин 5 сек + 2 ч 1 мин 44 сек) / 1 мин.","answer":"155","image":null,"solution":"Итог 2 ч 35 мин = 155 мин. /1 мин = 155.","note":null},{"num":4,"topic":"num","statement":"Вычислите: НОД(15,30)·НОД(12,16).","answer":"60","image":null,"solution":"15·4 = 60.","note":null},{"num":5,"topic":"eq","statement":"Найдите значение: 5(3x−3y−7) − 6(3x−2y−5) + 3(x+y+4).","answer":"7","image":null,"solution":"x и y сокращаются, остаётся −35+30+12 = 7.","note":null},{"num":6,"topic":"ratio","statement":"Расстояние 162 км, навстречу два велосипедиста 13 и 14 км/ч. Через сколько часов расстояние между ними впервые 27 км?","answer":"5","image":null,"solution":"(162−27)/27 = 5 ч.","note":null},{"num":7,"topic":"seq","statement":"Найдите число вместо вопросительного знака (по закономерности рисунка).","answer":"8","image":"/figures/v5_q7.svg","solution":"Центр = левое − верхнее. Для третьей ячейки 13 − 5 = 8.","note":null},{"num":8,"topic":"frac","statement":"Вычислите: |34,2| : |−1,9| + (5,55 − |−3,3|) − 0,25.","answer":"20","image":null,"solution":"18 + 2,25 − 0,25 = 20.","note":null},{"num":9,"topic":"geo","statement":"За сколько минут часовая стрелка поворачивается на 38 градусов?","answer":"76","image":null,"solution":"38 / 0,5 = 76 мин.","note":null},{"num":10,"topic":"ratio","statement":"584 кг апельсинов в 3 магазина. Первый:второй = 3:2, третий на 15% больше второго. Сколько в третий?","answer":"184","image":null,"solution":"7,3k=584 → k=80. Третий 2,3·80 = 184.","note":null},{"num":11,"topic":"num","statement":"В классе менее 50. 1/6 получили «5», 1/7 «4», 1/2 «3», остальные «2». Сколько «2»?","answer":"8","image":null,"solution":"Класс 42. 7+6+21=34. «2»: 42−34 = 8.","note":null},{"num":12,"topic":"eq","statement":"Решите уравнение: (4x+1)/3 − x = (3x−2)/2 − (x+2)/4.","answer":"2","image":null,"solution":"4x+4 = 15x−18 → x=2.","note":null},{"num":13,"topic":"comb","statement":"Шахматист 40 партий, 26 очков (победа 1, ничья 0,5, поражение 0). Разница числа побед и поражений?","answer":"12","image":null,"solution":"2w+d=52, w−l = 2w+d−40 = 12.","note":null},{"num":14,"topic":"work","statement":"Три каменщика — стену за 3 ч. Первый один за 5 ч, второй за 18 ч 45 мин. За сколько минут третий один?","answer":"750","image":null,"solution":"1/3 − 1/5 − 4/75 = 2/25 → 12,5 ч = 750 мин.","note":null},{"num":15,"topic":"frac","statement":"Вычислите: (162,162:2,25 + 0,828):0,0125 / (5,1·5,1 + 10,2·3,9 + 3,9·3,9).","answer":"72","image":null,"solution":"Числитель 5832, знаменатель (5,1+3,9)²=81. 5832/81 = 72.","note":null},{"num":16,"topic":"ratio","statement":"Асан круг за 8 мин, Марат за 10 мин, едут в одну сторону. Через сколько минут Асан догонит Марата?","answer":"40","image":null,"solution":"t(1/8−1/10)=1 → t=40 мин.","note":null},{"num":17,"topic":"eq","statement":"Найдите произведение корней уравнения |3x+12| = |−x|.","answer":"18","image":null,"solution":"x=−6 и x=−3. Произведение 18.","note":null},{"num":18,"topic":"sys","statement":"Найдите наименьшее целое решение: (1−x)/2 + 3 < 3x − (2x+1)/7.","answer":"2","image":null,"solution":"51 < 45x → x>1,13 → x=2.","note":null},{"num":19,"topic":"num","statement":"Страницы пронумерованы с 1. Из середины вырван двойной листочек, сумма четырёх номеров 130. Какой номер у последней страницы тетради?","answer":"64","image":null,"solution":"Пажи 31,32,33,34 (сумма 130) — центральные. Всего 64 страницы.","note":null},{"num":20,"topic":"num","statement":"Сумма всех натуральных n, при которых 80/(n+10) — натуральное число.","answer":"116","image":null,"solution":"n+10 ∈ {16,20,40,80} → n=6,10,30,70. Сумма 116.","note":null},{"num":21,"topic":"comb","statement":"Каждый звонок: 3 детей в маленькую аудиторию, половину оставшихся в большую. После 4-го звонка осталось 8. Сколько было до первого звонка?","answer":"173","image":null,"solution":"Обратно: a=2·next+3. 8→19→41→85→173.","note":null},{"num":22,"topic":"sys","statement":"4≤a≤5, 5≤b≤6. Сумма всех целых значений выражения 2a−b?","answer":"14","image":null,"solution":"2a−b ∈ [2,5]. Целые 2,3,4,5. Сумма 14.","note":null},{"num":23,"topic":"sys","statement":"Найдите сумму всех целых решений неравенства |3x−17| < 5.","answer":"18","image":null,"solution":"4<x<7,33 → x=5,6,7. Сумма 18.","note":null},{"num":24,"topic":"num","statement":"Вычислите: 1/3 + 2/3 − 3/3 + 4/3 + 5/3 − 6/3 + … + 106/3 + 107/3 − 108/3.","answer":"630","image":null,"solution":"Группа даёт k−1, 36 групп: Σ0..35 = 630.","note":null},{"num":25,"topic":"pct","statement":"Из 30 кг свежих яблок 4,8 кг сушёных (40% воды). Сколько г воды в 1000 г свежих яблок?","answer":"904","image":null,"solution":"Сухого вещества 2,88 кг. Вода в свежих 27,12/30 = 0,904 → 904 г.","note":null},{"num":26,"topic":"geo","statement":"На AC точка B. Полуокружности на AC и AB равны 12,56 см и 3,14 см. Чему равен отрезок BC? (π=3,14)","answer":"6","image":"/figures/v5_q26.svg","solution":"AC=8, AB=2 → BC=6.","note":null},{"num":27,"topic":"ratio","statement":"Из A в B (23 км) пешеход 4 км/ч. Через 12 мин из B навстречу велосипедист 14 км/ч. Через сколько минут после выезда велосипедиста встретятся?","answer":"74","image":null,"solution":"Пешеход прошёл 0,8 км. (23−0,8)/18 = 1,233 ч = 74 мин.","note":null},{"num":28,"topic":"geo","statement":"Из 6 равносторонних треугольников составили фигуру. Стороны треугольников 1–6: 9,12,14,9,15,11 см. Чему равен периметр фигуры?","answer":null,"image":"/figures/v5_q28.png","solution":"Периметр зависит от того, какие стороны внешние — в приложении показан рисунок, сверьте по нему.","note":null},{"num":29,"topic":"geo","statement":"Масштаб 1:100 000, лес прямоугольный 30 мм и 80 мм. Сколько гектаров?","answer":"2400","image":null,"solution":"Реально 3 км × 8 км = 24 км² = 2400 га.","note":null},{"num":30,"topic":"ratio","statement":"Первую четверть пути авто 84 км/ч, остальное 42 км/ч. Средняя скорость на всём пути?","answer":"48","image":null,"solution":"Время d/12, путь 4d → 48 км/ч.","note":null}]},{"id":"rfmsh2025_v7","title":"РФМШ 2025 · Вариант 7 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"geo","statement":"Длина прямоугольного параллелепипеда 4. Ширина в 6 раз больше длины, высота в 3 раза меньше ширины. Найдите объём.","answer":"768","image":null,"solution":"4·24·8 = 768.","note":null},{"num":2,"topic":"work","statement":"4 рабочих выполнили задание за 14 дней. Сколько рабочих нужно, чтобы выполнить за 8 дней?","answer":"7","image":null,"solution":"4·14/8 = 7.","note":null},{"num":3,"topic":"eq","statement":"Мурат в 3 раза старше Дамира, через 17 лет — в 2 раза. Сколько лет будет Дамиру через 17 лет?","answer":"34","image":null,"solution":"d=17. Через 17 лет 17+17 = 34.","note":null},{"num":4,"topic":"ratio","statement":"x+y+z=85, x:y=4:7, y:z=7:6. Найдите z.","answer":"30","image":null,"solution":"x:y:z = 4:7:6, 85/17=5, z=30.","note":null},{"num":5,"topic":"work","statement":"На доске 11 чисел, среднее 7. Какое 12-е число дописать, чтобы среднее 12 чисел тоже 7?","answer":"7","image":null,"solution":"84 − 77 = 7.","note":null},{"num":6,"topic":"frac","statement":"Вычислите: (3 1/3·1,9 + 19,5:4 1/2)/(62/75 − 0,16).","answer":"16","image":null,"solution":"(32/3)/(2/3) = 16.","note":null},{"num":7,"topic":"geo","statement":"Длина окружности 251,2. Найдите площадь круга (π=3,14).","answer":"5024","image":null,"solution":"r=40. S=3,14·1600 = 5024.","note":null},{"num":8,"topic":"comb","statement":"Если по 6 конфет — 7 останется, если по 7 — не хватит 6. Сколько детей?","answer":"13","image":null,"solution":"6n+7 = 7n−6 → n=13.","note":null},{"num":9,"topic":"work","statement":"Среднее 4 чисел 13, среднее 2 других 19. Найдите среднее всех шести.","answer":"15","image":null,"solution":"(52+38)/6 = 15.","note":null},{"num":10,"topic":"sys","statement":"17 любят мультфильмы, 14 детективы, 3 — и то, и другое, 3 — ни то ни другое. Сколько учеников в классе?","answer":"31","image":null,"solution":"(17+14−3)+3 = 31.","note":null},{"num":11,"topic":"comb","statement":"15 белых и 12 красных шаров. Асан вытащил 17. Наименьшее число красных среди них?","answer":"2","image":null,"solution":"Худший случай: 15 белых + 2 красных = 17.","note":null},{"num":12,"topic":"geo","statement":"Общая часть двух прямоугольников закрашена. Незакрашенная часть прямоугольника a×b равна 43. Найдите незакрашенную часть c×d, если a=9,b=12,c=15,d=10.","answer":"85","image":"/figures/v7_q12.svg","solution":"Наложение = 108−43 = 65. c·d − 65 = 150−65 = 85.","note":null},{"num":13,"topic":"num","statement":"Сумма двух натуральных 208. При делении большего на меньшее частное 3, остаток 36. Чему равно большее?","answer":"165","image":null,"solution":"4b=172 → b=43, a=165.","note":null},{"num":14,"topic":"sys","statement":"120 студентов: 101 ноутбук, 86 планшет, 13 ни то ни другое. У скольких и ноутбук, и планшет?","answer":"80","image":null,"solution":"107 = 101+86−x → x=80.","note":null},{"num":15,"topic":"num","statement":"В восьмизначном числе, кратном 45, заменили 2 цифры звёздочками: 154461**. Наибольшая сумма замененных цифр?","answer":"6","image":null,"solution":"Кратно 5 → b∈{0,5}. Кратно 9 → a+b∈{6,15}, 15 невозможно. Макс сумма 6.","note":null},{"num":16,"topic":"eq","statement":"Операция a⊕b = 2ab − b. Найдите корень уравнения 1⊕(2⊕x) = 111.","answer":"37","image":null,"solution":"2⊕x=3x, 1⊕3x=3x=111 → x=37.","note":null},{"num":17,"topic":"frac","statement":"Продали 2/7 тетрадей, затем 2/3 остатка, затем ещё 56. Осталось 4/21 всех. Сколько было?","answer":"1176","image":null,"solution":"1/21 T = 56 → T=1176.","note":null},{"num":18,"topic":"num","statement":"У каких натуральных чисел от 1 до 10 нечётное количество делителей?","answer":"1, 4, 9","image":null,"solution":"Нечётное число делителей — только у точных квадратов: 1, 4, 9.","note":null},{"num":19,"topic":"comb","statement":"100 человек, лжецы и правдивые, у каждого одно любимое время года. На вопросы про зиму/весну/лето/осень «да» ответили 45,50,50,55. Сколько лжецов?","answer":"50","image":null,"solution":"t+3l=200, t+l=100 → l=50.","note":null},{"num":20,"topic":"seq","statement":"Последовательность: 111, 213, 141, 516, 171, 819, ?, 122. Найдите число вместо вопросительного знака.","answer":"201","image":null,"solution":"Нечётные члены 111,141,171,… растут на 30 → 201.","note":null},{"num":21,"topic":"geo","statement":"Прямоугольник разделён на 9 меньших. Известны периметры: 10, C=8, 7, A=11, 9. Найдите периметр B.","answer":"7","image":"/figures/v7_q21.svg","solution":"Через ширины столбцов и высоты строк: B = 2(w2+h2) = 7.","note":null},{"num":22,"topic":"sys","statement":"Найдите сумму натуральных решений системы: (2x−4)/5 + (2−x)/2 < 2; (2x+4)/3 − x/4 ≤ 3.","answer":"10","image":null,"solution":"x≤4 (и x>−18). Натуральные 1,2,3,4. Сумма 10.","note":null},{"num":23,"topic":"geo","statement":"Фигура из квадрата (периметр 16 см) и трёх одинаковых треугольников (периметр каждого 9 см). Чему равен периметр фигуры?","answer":null,"image":"/figures/v7_q23.png","solution":"Периметр зависит от того, как треугольники приставлены к квадрату — в приложении показан рисунок, сверьте по нему.","note":null},{"num":24,"topic":"ratio","statement":"Теплоход туда-обратно за 6,3 ч. Скорость в стоячей воде 18 км/ч, течение 2 км/ч. Расстояние между пристанями?","answer":"56","image":null,"solution":"d/20 + d/16 = 6,3 → d=56 км.","note":null},{"num":25,"topic":"num","statement":"Белый шоколад по 14 в коробке, чёрный по 17. Всего 175 штук. Сколько всего распаковали коробок?","answer":"11","image":null,"solution":"14·4 + 17·7 = 175 → коробок 4+7 = 11.","note":null},{"num":26,"topic":"num","statement":"Облачных дней на 14 больше, чем дождливых/снежных, и на 259 меньше солнечных. Сколько солнечных, если в году 365 дней?","answer":"299","image":null,"solution":"3r+287=365 → r=26. Солнечных 26+273 = 299.","note":null},{"num":27,"topic":"num","statement":"A — первые 5 простых, B — первые 5 неотрицательных чётных, C — первые 5 нечётных натуральных. Найдите сумму элементов (B∪C)∩A.","answer":"17","image":null,"solution":"(B∪C)={0..9}, ∩A={2,3,5,7}. Сумма 17.","note":null},{"num":28,"topic":"comb","statement":"Сколькими способами вписать 4,5,6,7,8 (каждое по разу), чтобы неравенства □>□>□<□<□ были верны?","answer":"6","image":"/figures/v7_q28.svg","solution":"Минимум 4 в центре. Выбрать 2 из {5,6,7,8} налево: C(4,2)=6.","note":null},{"num":29,"topic":"pct","statement":"1-я неделя: цена 350000 тг. 2-я: покупателей +40%, выручка +24%. На сколько тг снизили цену?","answer":"40000","image":null,"solution":"Цена2 = 350000·1,24/1,4 = 310000. Снижение 40000.","note":null},{"num":30,"topic":"sys","statement":"Найдите сумму всех целых x, НЕ являющихся решениями неравенства ||2x−20|−21| > 3.","answer":"80","image":null,"solution":"|2x−20|∈[18,24] → x=19..22 и x=−2..1. Сумма 80.","note":null}]},{"id":"rfmsh2025_v8","title":"РФМШ 2025 · Вариант 8 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"frac","statement":"Числа x=4/5, y=10/12, z=3/4, t=14/15. m — сумма наибольшего и наименьшего. Чему равно 60m?","answer":"101","image":null,"solution":"","note":null},{"num":2,"topic":"frac","statement":"У Миши было 7200 тг. 1/3 — на книгу, 1/6 — на тетради, 4/15 — на карандаши, остальное — на альбом. Сколько тг на альбом?","answer":"1680","image":null,"solution":"","note":null},{"num":3,"topic":"geo","statement":"Маляр покрасил 4 прямоугольные стены за 6 часов. Длина стены 8 м, ширина на 2 м меньше. Какую площадь (м²) он красит за 1 час?","answer":"32","image":null,"solution":"","note":null},{"num":4,"topic":"geo","statement":"Сколько градусов составляет угол, равный разности 5/6 развёрнутого угла и 6/5 прямого угла?","answer":"42","image":null,"solution":"","note":null},{"num":5,"topic":"seq","statement":"В феврале переплели 111 книг, каждый следующий месяц на 11 больше. Сколько книг переплели в ноябре?","answer":"210","image":null,"solution":"","note":null},{"num":6,"topic":"ratio","statement":"Поездка на 3 дня в Боровое: билет в одну сторону 1100 тг, проживание 3200 тг/сутки, питание 1600 тг. Сколько потратит каждый?","answer":null,"image":null,"solution":"","note":"Условие допускает разное число суток — нужен официальный ключ."},{"num":7,"topic":"num","statement":"Какова сумма всех целых чисел между −14,32 и 22,24?","answer":"148","image":null,"solution":"","note":null},{"num":8,"topic":"ratio","statement":"Велосипедист проехал 49 км за 3 часа, каждый час вдвое меньше предыдущего. Сколько км за последний час?","answer":"7","image":null,"solution":"","note":null},{"num":9,"topic":"comb","statement":"Мариям: «Дай мне 8 конфет — станет в 2 раза больше, чем у тебя». Дария: «Лучше дай мне 8 — станет поровну». Сколько конфет у Мариям?","answer":"56","image":null,"solution":"","note":null},{"num":10,"topic":"num","statement":"Наименьшее число раз подряд записать 2020, чтобы результат делился на 9?","answer":"9","image":null,"solution":"","note":null},{"num":11,"topic":"ratio","statement":"Из 1 л молока — 150 г сливок, из 1 кг сливок — 300 г масла. Сколько г масла из 100 л молока?","answer":"4500","image":null,"solution":"","note":null},{"num":12,"topic":"eq","statement":"Сумма двух чисел 25. Первое увеличили в 2 раза, второе в 5 раз — новая сумма 107. Найдите второе число.","answer":"19","image":null,"solution":"","note":null},{"num":13,"topic":"eq","statement":"Два года назад брат был в 2 раза старше сестры, 8 лет назад — в 5 раз. Найдите разницу их возрастов.","answer":"8","image":null,"solution":"","note":null},{"num":14,"topic":"comb","statement":"Дамир делает 5 выстрелов, за каждое попадание +2 выстрела. Всего выстрелил 25 раз. Сколько попал?","answer":"10","image":null,"solution":"","note":null},{"num":15,"topic":"sys","statement":"Найдите произведение двух наибольших целых решений: (2x+5)/4 − (2x−3)/5 + 1/20 + x/10 < (1−x)/2.","answer":"12","image":null,"solution":"","note":null},{"num":16,"topic":"comb","statement":"В ящике 10 красных, 8 синих, 8 зелёных, 4 жёлтых. Наименьшее число карандашей, чтобы был хотя бы один каждого цвета?","answer":"27","image":null,"solution":"","note":null},{"num":17,"topic":"eq","statement":"Зная x−2y=10/15, найдите: 2(3x−6y)+1,2y+1,5(4y−2x)+1,5x−4,2y.","answer":"3","image":null,"solution":"","note":null},{"num":18,"topic":"num","statement":"Число a при делении на 5 даёт остаток 1, на 3 — остаток 2. Сумма остатков при делении a на 15 и 3?","answer":"13","image":null,"solution":"","note":null},{"num":19,"topic":"geo","statement":"Куб с ребром 1 м покрасили и разрезали на кубики 1 см. Сколько кубиков имеют 2 крашеные грани?","answer":"1176","image":null,"solution":"","note":null},{"num":20,"topic":"work","statement":"6«А» — за 180 мин, вместе с 6«Б» — за 120 мин. Сначала 6«Б» один, через 1,5 ч подключился 6«А». Сколько минут работали вместе?","answer":"90","image":null,"solution":"","note":null},{"num":21,"topic":"pct","statement":"Продавая 1 кг за 2,2 тыс. тг, магазин имеет 10% прибыли. При цене 1,8 тыс. — убыток 43 тыс. тг. Сколько кг было?","answer":"215","image":null,"solution":"","note":null},{"num":22,"topic":"pct","statement":"Магазин купил 28 альбомов за 50400 тг, наценка 20%, продал 15. Остальные — с доп. наценкой 10% к стоимости. Найдите прибыль.","answer":"12420","image":null,"solution":"","note":"Ответ зависит от трактовки доп. наценки — сверьте с ключом."},{"num":23,"topic":"frac","statement":"Вычислите: 100 · (4,08:1,1:6,8·13,2:4) / (0,002:2,4·8·0,2:0,001).","answer":null,"image":null,"solution":"","note":"Порядок действий в исходнике неоднозначен — нужен официальный ключ."},{"num":24,"topic":"comb","statement":"Одним пакетиком заваривают 2 или 3 стакана. Коробку поделили поровну. Мирас заварил 57 стаканов, Баглан 83. Сколько пакетиков в коробке?","answer":"56","image":null,"solution":"","note":null},{"num":25,"topic":"num","statement":"Найдите произведение всех целых a: |a|<4,3 и |a|>2,8.","answer":"144","image":null,"solution":"","note":null},{"num":26,"topic":"ratio","statement":"Три рыбака: каждый отпускает 1 рыбу и забирает 1/2 остатка. После третьего осталось 15. Сколько поймали всего?","answer":"127","image":null,"solution":"","note":null},{"num":27,"topic":"comb","statement":"Из книги выпало несколько подряд идущих листов. Первая страница 387, последняя — те же цифры в другом порядке. Сколько листов выпало?","answer":"176","image":null,"solution":"","note":null},{"num":28,"topic":"geo","statement":"Укажите точку, симметричную B(−32) относительно A(4).","answer":"40","image":null,"solution":"","note":null},{"num":29,"topic":"geo","statement":"Часы показывают 11:15. Какой угол (180..360) между стрелками через 85 минут?","answer":"220","image":null,"solution":"","note":null},{"num":30,"topic":"ratio","statement":"После 7 стирок каждое из трёх измерений мыла уменьшалось вдвое. На сколько стирок хватит оставшегося?","answer":"1","image":null,"solution":"","note":"7 стирок → объём 1/8; остатка хватит на 1 стирку."}]},{"id":"rfmsh2025_v9","title":"РФМШ 2025 · Вариант 9 · 7 класс","timeLimitMin":120,"school":"РФМШ","questions":[{"num":1,"topic":"frac","statement":"Выполните действие: ((16 ч 32 мин) − (12 ч 50 мин)) : (37 мин).","answer":"6","image":null,"solution":"3 ч 42 мин = 222 мин. 222/37 = 6.","note":null},{"num":2,"topic":"geo","statement":"Черепаха вышла из дома и вернулась. По графику движения определите расстояние (в метрах) от дома через 3 мин.","answer":null,"image":"/figures/v9_q2.png","solution":"Значение считывается с графика — в приложении показан рисунок.","note":null},{"num":3,"topic":"pct","statement":"Сплав содержит 18% меди. Сколько кг сплава нужно, чтобы в нём было 54 кг меди?","answer":"300","image":null,"solution":"54/0,18 = 300.","note":null},{"num":4,"topic":"ratio","statement":"Периметр треугольника 125 см, стороны 4:9:12. Найдите наибольшую сторону.","answer":"60","image":null,"solution":"125/25=5, 12·5 = 60.","note":null},{"num":5,"topic":"num","statement":"Какую наибольшую цифру можно поставить вместо звёздочки, чтобы −6,5*7 > −6,586?","answer":"7","image":null,"solution":"6,5d7 < 6,586 → d≤7. Наибольшая 7.","note":null},{"num":6,"topic":"seq","statement":"Ряд 0,2,6,12,20,30,42. Записали ещё два члена. Модуль их разности?","answer":"16","image":null,"solution":"Дальше 56 и 72. |72−56| = 16.","note":null},{"num":7,"topic":"eq","statement":"Второе число на 3 больше первого. Частное первого на 4 равно частному второго на 5. Найдите первое число.","answer":"12","image":null,"solution":"a/4=(a+3)/5 → a=12.","note":null},{"num":8,"topic":"frac","statement":"1-й день 30% поля, 2-й — 9/14 остатка, 3-й — остальные 15 га. Площадь поля?","answer":"60","image":null,"solution":"0,25P = 15 → P=60 га.","note":null},{"num":9,"topic":"comb","statement":"Каждому по 7 конфет — останется 4; по 9 — не хватит 24. Сколько друзей?","answer":"14","image":null,"solution":"2f=28 → f=14.","note":null},{"num":10,"topic":"eq","statement":"Арман нашёл на 18 больше половины грибов папы. Папа на 7 больше Армана. Сколько грибов вместе?","answer":"93","image":null,"solution":"Арман 43, папа 50. Вместе 93.","note":null},{"num":11,"topic":"eq","statement":"Сумма трёх чисел на 16 больше первого, на 11 больше второго, на 9 больше третьего. Найдите произведение этих чисел.","answer":"126","image":null,"solution":"Сумма 18. Числа 2,7,9. 2·7·9 = 126.","note":null},{"num":12,"topic":"eq","statement":"Операция a⊕b = 2a+3b. Найдите ((2m)⊕n) ⊕ (m⊕(2n)) при m=3, n=5.","answer":"162","image":null,"solution":"27⊕36 = 54+108 = 162.","note":null},{"num":13,"topic":"geo","statement":"Какой угол (0..180) образуют стрелки в 10 часов 22 минуты?","answer":"179","image":null,"solution":"|311 − 132| = 179°.","note":null},{"num":14,"topic":"geo","statement":"Квадрат со стороной 10 разрезали на 4 квадрата. Внутри отрезки AB, DC и дуги AD, BC (четверти радиуса 5). Найдите сумму площадей закрашенных частей.","answer":null,"image":"/figures/v9_q14.png","solution":"Площадь считается по рисунку (дуги и отрезки) — в приложении показан чертёж.","note":null},{"num":15,"topic":"comb","statement":"Пять детей в шеренге, 37 флажков. Справа от Сабыржана 14, от Дамира 32, от Айгерим 20, от Куаныша 8. Сколько флажков у Меруерт?","answer":"8","image":null,"solution":"Меруерт справа никого → у неё 8 флажков.","note":null},{"num":16,"topic":"ratio","statement":"13 тугриков = 26 динаров, 28 рупий = 21 динар, 14 рупий = 3 талера, 7 крон = 4 талера. Сколько тугриков за 21 крону?","answer":"21","image":null,"solution":"21 крон → 12 талер → 56 рупий → 42 динара → 21 тугрик.","note":null},{"num":17,"topic":"seq","statement":"В числовом треугольнике каждое число — сумma трёх над ним. Найдите сумму чисел, замененных вопросительными знаками.","answer":"31","image":"/figures/v9_q17.svg","solution":"? = 6, 6 (4-я строка) и 19 (центр 5-й). Сумма 6+6+19 = 31.","note":null},{"num":18,"topic":"spat","statement":"Куб объёмом 8 дм³ состоит из кубиков со стороной 1 см. Длина цепочки из всех кубиков в метрах?","answer":"80","image":null,"solution":"8000 кубиков × 1 см = 8000 см = 80 м.","note":null},{"num":19,"topic":"sys","statement":"Найдите сумму всех целых решений: −5/6 < 5 1/2 − x < 2 1/6.","answer":"15","image":null,"solution":"3,33<x<6,33 → x=4,5,6. Сумма 15.","note":null},{"num":20,"topic":"frac","statement":"Вычислите: (1+1/2)(1+1/3)(1+1/4)…(1+1/99).","answer":"50","image":null,"solution":"Телескоп: 100/2 = 50.","note":null},{"num":21,"topic":"ratio","statement":"Из A в B (10 км) турист 7 1/2 км/ч. Одновременно из B в том же направлении второй, скорость в 2 1/4 раза меньше. Через сколько минут первый догонит второго?","answer":"144","image":null,"solution":"Отн. скорость 12,5/3 км/ч. 10/(12,5/3) = 2,4 ч = 144 мин.","note":null},{"num":22,"topic":"num","statement":"17! = 35568*428096000. Какая цифра должна стоять вместо звёздочки?","answer":"7","image":null,"solution":"17! = 355687428096000 → * = 7.","note":null},{"num":23,"topic":"sys","statement":"При каком натуральном n двойное неравенство 20 < |x−10| < n имеет ровно 13 натуральных решений?","answer":"34","image":null,"solution":"x=31..43 (13 шт) → 43<10+n≤44 → n=34.","note":null},{"num":24,"topic":"num","statement":"Вычислите: 1+2−3+4+5−6+7+8−9+…+91+92−93.","answer":"1395","image":null,"solution":"31 группа, группа k даёт 3k−3. Сумма 1395.","note":null},{"num":25,"topic":"geo","statement":"Вершины прямоугольника ABCD: A(−2;−3), B(−2;5), C(4;5). Найдите сумму координат точки пересечения диагоналей.","answer":"2","image":null,"solution":"Центр = середина AC = (1;1). Сумма 2.","note":null},{"num":26,"topic":"num","statement":"Сколько натуральных пар (x,y): x+y<200 и 5x=7y?","answer":"16","image":null,"solution":"x=7k, y=5k, 12k<200 → k=1..16 → 16 пар.","note":null},{"num":27,"topic":"comb","statement":"На плане дома соседние комнаты соединены дверью. Сколькими способами пройти из A в B, не проходя ни одну комнату дважды?","answer":null,"image":"/figures/v9_q27.png","solution":"Число путей считается по плану — в приложении показан рисунок.","note":null},{"num":28,"topic":"pct","statement":"Среднее двух положительных чисел на 30% меньше большего. На сколько % это среднее больше меньшего?","answer":"75%","image":null,"solution":"b=0,4a, среднее 0,7a. (0,7−0,4)/0,4 = 75%.","note":null},{"num":29,"topic":"eq","statement":"Найдите корень уравнения: x(x−3)/9 − 2(x²+9)/36 = (x−3)(x+6)/18.","answer":"1","image":null,"solution":"После упрощения −18x = −18 → x=1.","note":null},{"num":30,"topic":"num","statement":"К 50-значному числу из одних 7 прибавили 50-значное из одних 9. Чему равна сумма цифр полученной суммы?","answer":"350","image":null,"solution":"Сумма = 1, затем 49 семёрок, затем 6. 1+49·7+6 = 350.","note":null}]},{"id":"bil_v13","title":"БИЛ · Байқау сынағы · нұсқа 13","timeLimitMin":60,"school":"БИЛ","questions":[{"num":2,"topic":"eq","statement":"Найдите значение выражения: 4(15x+8)+3(6x−5), при x=4.","answer":"329","image":null,"solution":"4(60+8)+3(24−5)=272+57=329.","note":null},{"num":3,"topic":"eq","statement":"Упростите и найдите значение: (18·9+x)+(y+722:19), при x=36, y=14.","answer":"250","image":null,"solution":"(162+36)+(14+38)=198+52=250.","note":null},{"num":4,"topic":"eq","statement":"Решите уравнение: 91+48:(11−b)=99.","answer":"5","image":null,"solution":"48/(11−b)=8 → 11−b=6 → b=5.","note":null},{"num":5,"topic":"ratio","statement":"Кызылорда–Алматы 1170 км. Поезд из Кызылорды 70 км/ч ехал 6 ч, затем навстречу из Алматы вышел поезд 80 км/ч. Сколько часов едет поезд из Алматы до встречи?","answer":"5","image":null,"solution":"Проехал 420 км, осталось 750. 750/(70+80)=5 ч.","note":null},{"num":6,"topic":"eq","statement":"Решите уравнение: 86−49:(2x−5)=79.","answer":"6","image":null,"solution":"49/(2x−5)=7 → 2x−5=7 → x=6.","note":null},{"num":7,"topic":"eq","statement":"Упростите и найдите значение: 8(2x+y)+3(x−y), при x=2, y=9.","answer":"83","image":null,"solution":"8·13+3·(−7)=104−21=83.","note":null},{"num":8,"topic":"eq","statement":"Упростите: (161x−92x):23+17x.","answer":"20x","image":null,"solution":"69x/23+17x=3x+17x=20x.","note":null},{"num":9,"topic":"eq","statement":"Упростите и найдите значение: 5(6x+7y)+2(4x−15y), при x=3, y=6.","answer":"144","image":null,"solution":"38x+5y=114+30=144.","note":null},{"num":10,"topic":"eq","statement":"Упростите: (581y·5):83−18y.","answer":"17y","image":null,"solution":"2905y/83−18y=35y−18y=17y.","note":null},{"num":13,"topic":"num","statement":"Частное двух чисел равно НОД(28,20). Разность этих чисел равна НОК(7,9). Найдите эти числа.","answer":"84 и 21","image":null,"solution":"НОД=4, НОК=63. a=4b, 3b=63 → b=21, a=84.","note":null},{"num":14,"topic":"eq","statement":"Упростите: 203·4x−750x+90:15+14.","answer":"62x+20","image":null,"solution":"812x−750x+6+14=62x+20.","note":null},{"num":15,"topic":"eq","statement":"Упростите: 18·7x−270x:45+35x.","answer":"155x","image":null,"solution":"126x−6x+35x=155x.","note":null},{"num":16,"topic":"eq","statement":"Выполните деление: (245a+147b−98c):49.","answer":"5a+3b−2c","image":null,"solution":"245/49=5, 147/49=3, 98/49=2 → 5a+3b−2c.","note":null},{"num":17,"topic":"num","statement":"Частное двух чисел равно НОД(35,77). Сумма этих чисел равна НОД(160,96). Найдите эти числа.","answer":"4 и 28","image":null,"solution":"НОД=7, НОД(160,96)=32. a=7b, 8b=32 → b=4, a=28.","note":null},{"num":20,"topic":"work","statement":"14 старшим и 8 начальным классам раздали x кусков мела. Каждому старшему классу выделяется y кусков. Сколько кусков каждому начальному классу? x=36, y=2.","answer":"1","image":null,"solution":"Старшим 14·2=28, осталось 8 на 8 классов → по 1.","note":null},{"num":27,"topic":"eq","statement":"Решите уравнение: 71,93+y=98,15.","answer":"26,22","image":null,"solution":"98,15−71,93=26,22.","note":null},{"num":28,"topic":"eq","statement":"Ученик задумал число, прибавил 14,8, уменьшил результат на 3,56 и получил 75,29. Какое число он задумал?","answer":"64,05","image":null,"solution":"75,29−14,8+3,56=64,05.","note":null},{"num":29,"topic":"frac","statement":"Вычислите, используя распределительное свойство: 10,27·5,1+8,3·5,1.","answer":"94,707","image":null,"solution":"5,1·(10,27+8,3)=5,1·18,57=94,707.","note":null},{"num":31,"topic":"pct","statement":"Расстояние авто проехал за 3 часа. За 1-й час — 37,5% всего пути, за 2-й час — 36% оставшегося. Сколько процентов всего пути проехал за 3-й час?","answer":"40%","image":null,"solution":"Осталось 62,5%. 2-й час 36%·62,5%=22,5%. 3-й: 100−37,5−22,5=40%.","note":null},{"num":32,"topic":"eq","statement":"Упростите и найдите значение: 4(b+0,8)+1,7b, при b=2,3.","answer":"16,31","image":null,"solution":"5,7b+3,2=13,11+3,2=16,31.","note":null},{"num":33,"topic":"pct","statement":"Сколько граммов воды добавить в 150 г раствора соды с концентрацией 40%, чтобы получить концентрацию 15%?","answer":"250","image":null,"solution":"Соды 60 г. 60/(150+x)=0,15 → 150+x=400 → x=250.","note":null},{"num":34,"topic":"geo","statement":"Отношение ширины прямоугольника к длине 3:5. Длина на 6 см больше ширины. Найдите периметр.","answer":"48","image":null,"solution":"2k=6 → k=3. Ширина 9, длина 15. P=2(9+15)=48.","note":null},{"num":35,"topic":"eq","statement":"Упростите и найдите значение: 6(a+1,5)−2,8a, при a=1,5.","answer":"13,8","image":null,"solution":"3,2a+9=4,8+9=13,8.","note":null},{"num":39,"topic":"eq","statement":"Решите уравнение: (7−0,2x)·1,4=7,56.","answer":"8","image":null,"solution":"7−0,2x=5,4 → 0,2x=1,6 → x=8.","note":null},{"num":42,"topic":"seq","statement":"Найдите следующее число: 5, 8, 6, 12, 8, 17, 11, 23, 15, 30, ?","answer":"20","image":null,"solution":"Нечётные члены 5,6,8,11,15,? растут на 1,2,3,4,5 → 20.","note":null},{"num":1,"topic":"ratio","statement":"Теплоход с собственной скоростью 19 км/ч проплыл 2 часа по течению и 3 часа против течения. Скорость реки 2 км/ч. Какую часть всего пути теплоход плыл против течения?","answer":"17/31","image":null,"solution":"По течению 21·2=42 км, против 17·3=51 км. Всего 93. Против: 51/93=17/31.","note":null},{"num":24,"topic":"eq","statement":"Упростите: (128a+35b)·9−1100a−315b.","answer":"52a","image":null,"solution":"1152a+315b−1100a−315b=52a.","note":null},{"num":49,"topic":"comb","statement":"Дана операция: 1∘2=4, 2∘3=18, 3∘4=48. Чему равно 3∘5?","answer":"75","image":null,"solution":"a∘b = a·b². 3·5²=3·25=75.","note":null}]}];
